27	#[derive(Parser)]
28	#[command(
29	    name = "kuda",
30	    version,
31	    about = "PC monitoring harness with LLM-driven investigation"
32	)]
33	struct Cli {
34	    /// Log at debug level and mirror the log to stderr
35	    #[arg(long, global = true)]
36	    verbose: bool,
37	
38	    #[command(subcommand)]
39	    command: Command,
40	}
41	
42	#[derive(Subcommand)]
43	enum Command {
44	    /// Run one monitoring cycle (this is what the scheduler invokes)
45	    Check {
46	        /// Probe every watch even if its interval has not elapsed
47	        #[arg(long)]
48	        force: bool,
49	    },
50	    /// Take snapshots and store each successful collector as last_known_good
51	    Snapshot {
52	        /// Ignore snapshot_interval and the retry interval
53	        #[arg(long)]
54	        force: bool,
55	        /// Limit to one watch
56	        #[arg(long)]
57	        watch: Option<String>,
58	    },
59	    /// Build an incident directory and investigate it with an LLM
60	    Diagnose {
61	        /// Name of the watch to investigate (the `name` of a [[watch]] in the config;
62	        /// it must have a [watch.diagnose] table)
63	        #[arg(long)]
64	        watch: String,
65	        /// Only build the incident directory; do not call an LLM
66	        #[arg(long)]
67	        dry_run: bool,
68	        /// Use this backend instead of the one in the config
69	        #[arg(long)]
70	        backend: Option<String>,
71	        /// Investigate an existing incident directory
72	        #[arg(long)]
73	        incident: Option<std::path::PathBuf>,
74	        /// Show desktop notifications when the investigation starts and ends
75	        #[arg(long)]
76	        notify: bool,
77	    },
78	    /// Show samples, baselines, snapshots and cooldowns for each watch
79	    Status,
80	    /// Validate the config file and everything it refers to
81	    CheckConfig,
82	    /// Show whether each LLM backend is available
83	    CheckBackends,
84	}
85	
86	fn run(cli: Cli) -> Result<()> {
87	    let paths = Paths::from_env()?;
88	    paths.ensure_dirs()?;
89	    logging::init(&paths.logs_dir, cli.verbose)?;
90	
91	    let config_path = paths.config_file();
92	    commands::log_paths(&paths, &config_path);
93	    let config = Config::load(&config_path)?;
94	    logging::set_level(config.general.log_level, cli.verbose);
95	
96	    match cli.command {
97	        Command::Check { force } => commands::check(&config, &paths, force),
98	        Command::Snapshot { force, watch } => {
99	            commands::snapshot(&config, &paths, force, watch.as_deref())
100	        }
101	        Command::Diagnose {
102	            watch,
103	            dry_run,
104	            backend,
105	            incident,
106	            notify,
107	        } => commands::diagnose(
108	            &config,
109	            &paths,
110	            commands::DiagnoseOptions {
111	                watch,
112	                dry_run,
113	                backend,
114	                incident,
115	                notify,
116	            },
117	        ),
118	        Command::Status => commands::status(&config, &paths),
119	        Command::CheckConfig => commands::check_config(&config, &paths),
120	        Command::CheckBackends => commands::check_backends(&config),
121	    }
122	}
123	
124	pub fn main() -> ExitCode {
125	    match run(Cli::parse()) {
126	        Ok(()) => ExitCode::SUCCESS,
127	        Err(error) => {
128	            // ログ初期化前の失敗もあるので、標準エラーにも必ず出す
129	            log::error!("{error:#}");
130	            if log::max_level() == log::LevelFilter::Off {
131	                eprintln!("error: {error:#}");
132	            }
133	            ExitCode::FAILURE
134	        }
135	    }
136	}
