25	/// 事件の metrics.csv に載せる probe の回数（5 分間隔で 24 時間分）
26	const INCIDENT_HISTORY_RUNS: u32 = 288;
27	
28	fn now() -> i64 {
29	    Local::now().timestamp()
30	}
31	
32	/// スケジューラの起動はぴったり interval おきとは限らない。わずかに早い起動で
33	/// 1 周まるごと飛ばさないよう、interval の 1 割（最大 30 秒）の早まりを許す
34	fn is_due(last: Option<i64>, now: i64, interval: Duration) -> bool {
35	    let Some(last) = last else {
36	        return true;
37	    };
38	    let interval = interval.as_secs() as i64;
39	    now - last >= interval - (interval / 10).min(30)
40	}
41	
42	/// collector が失敗した取得の後は、snapshot_interval を待たずにこの間隔で取り直す
43	const SNAPSHOT_RETRY_INTERVAL: Duration = Duration::from_secs(30 * 60);
44	
45	/// スナップショットを取る時期か。最後の取得で全 collector が成功していれば snapshot_interval、
46	/// 失敗した collector があれば再試行の間隔（snapshot_interval が短ければそちら）を、
47	/// 最後の取得から空ける
48	fn is_snapshot_due(state: &WatchState, now: i64, interval: Duration) -> bool {
49	    let wait = if state.last_snapshot_complete == Some(true) {
50	        interval
51	    } else {
52	        interval.min(SNAPSHOT_RETRY_INTERVAL)
53	    };
54	    is_due(state.last_snapshot, now, wait)
55	}
