57	/// スナップショットを取り、取得履歴と比較基準に記録する
58	fn take_snapshot(store: &Store, watch: &Watch, now: i64) -> Result<Value> {
59	    let snapshot = collector::take_snapshot(&watch.baseline.snapshot_collectors, now);
60	    let keep = watch.baseline.keep_good_snapshots;
61	    store.record_snapshot(&watch.name, now, &snapshot, keep)?;
62	    Ok(snapshot)
63	}
