65	pub fn check(config: &Config, paths: &Paths, force: bool) -> Result<()> {
66	    if !lock::hold_until_exit(&paths.lock_file())? {
67	        log::info!("another check is running; skipping");
68	        return Ok(());
69	    }
70	    let mut store = Store::open(&paths.db_file())?;
71	    let mut failures = 0;
72	    for watch in &config.watches {
73	        // 1 つの watch の失敗で他の監視を止めない
74	        if let Err(error) = check_watch(&mut store, paths, watch, force, now()) {
75	            failures += 1;
76	            log::error!("watch {}: {error:#}", watch.name);
77	        }
78	    }
79	
80	    logging::prune(
81	        &paths.logs_dir,
82	        config.general.log_retention_days,
83	        Local::now().date_naive(),
84	    )?;
85	    incident::prune(
86	        &paths.incidents_dir,
87	        config.general.incident_retention_days,
88	        now(),
89	    )?;
90	    if failures > 0 {
91	        bail!("{failures} watch(es) failed");
92	    }
93	    Ok(())
94	}
95	
96	fn check_watch(
97	    store: &mut Store,
98	    paths: &Paths,
99	    watch: &Watch,
100	    force: bool,
101	    now: i64,
102	) -> Result<()> {
103	    let mut state = store.load_state(&watch.name)?;
104	    if !force && !is_due(state.last_probe, now, watch.interval) {
105	        log::debug!("{}: interval has not elapsed", watch.name);
106	        return Ok(());
107	    }
108	
109	    let run = probe::run(&watch.probe, now);
110	    let mut metrics = run.metrics();
111	    let classification = match &run.processes {
112	        Some(processes) => {
113	            let classification = classify_processes(store, paths, watch, processes, &metrics, now)?;
114	            metrics.extend(classification.metrics.clone());
115	            Some(classification)
116	        }
117	        None => None,
118	    };
119	    log_run(watch, &run, &metrics);
120	
121	    let stats = baseline::stats(store, &watch.name, &watch.baseline, now)?;
122	    let mut variables = metrics.clone();
123	    variables.extend(baseline::variables(&stats));
124	    let matched = trigger_matches(watch, &variables);
125	
126	    store.record_run(&watch.name, &run)?;
127	    if let Some(classification) = &classification {
128	        classification.record(store, &watch.name, now)?;
129	    }
130	    let retention = watch.baseline.metrics_retention.as_secs() as i64;
131	    store.prune_metrics(&watch.name, now - retention)?;
132	    state.last_probe = Some(now);
133	
134	    // 異常時の値でベースラインと last_known_good を汚さない
135	    let healthy = !matched && metrics["loss"] < 1.0;
136	    if healthy {
137	        baseline::update(store, &watch.name, &watch.baseline, &metrics, now)?;
138	        if is_snapshot_due(&state, now, watch.baseline.snapshot_interval)
139	            && !watch.baseline.snapshot_collectors.is_empty()
140	        {
141	            take_snapshot(store, watch, now)?;
142	        }
143	    }
144	
145	    let Some(trigger) = &watch.trigger else {
146	        store.save_state(&watch.name, &state)?;
147	        return Ok(());
148	    };
149	    let since = state.trigger.since;
150	    let outcome = trigger::advance(&mut state.trigger, matched, trigger, now);
151	    // 発火の処理で失敗しても二重に発火しないよう、先に状態を保存する
152	    store.save_state(&watch.name, &state)?;
153	    log::debug!("{}: trigger outcome {outcome:?}", watch.name);
154	
155	    match outcome {
156	        Outcome::Fired => {
157	            let since = state.trigger.since.unwrap_or(now);
158	            let reason = format!(
159	                "{} が {} 回連続で成立",
160	                trigger.when.source(),
161	                state.trigger.streak
162	            );
163	            let pending = classification
164	                .as_ref()
165	                .map(Classification::pending_identities)
166	                .unwrap_or_default();
167	            fire(store, paths, watch, &run, &stats, since, &reason, &pending)
168	        }
169	        Outcome::Suppressed => {
170	            log::info!("{}: in cooldown, not firing", watch.name);
171	            Ok(())
172	        }
173	        Outcome::Recovered if trigger.recover_notify => {
174	            write_recovery(paths, &watch.name, since.unwrap_or(now), now)
175	        }
176	        Outcome::Recovered => {
177	            log::info!("{}: recovered", watch.name);
178	            Ok(())
179	        }
180	        Outcome::Normal | Outcome::Pending => Ok(()),
181	    }
182	}
