184	fn log_run(watch: &Watch, run: &ProbeRun, metrics: &Variables) {
185	    log::info!("{}: {metrics:?}", watch.name);
186	    for result in &run.results {
187	        log::debug!(
188	            "{}: {} ok={} rtt_ms={:?} error={:?}",
189	            watch.name,
190	            result.target,
191	            result.ok,
192	            result.rtt_ms,
193	            result.error
194	        );
195	    }
196	}
