198	fn build_incident(
199	    store: &Store,
200	    paths: &Paths,
201	    watch: &Watch,
202	    run: &ProbeRun,
203	    stats: &[SeriesStats],
204	    since: i64,
205	    reason: &str,
206	) -> Result<Incident> {
207	    let created = now();
208	    let current = collector::take_snapshot(&watch.baseline.snapshot_collectors, created);
209	    let collectors: Vec<String> = watch
210	        .baseline
211	        .snapshot_collectors
212	        .iter()
213	        .map(|spec| spec.name())
214	        .collect();
215	    let last_good = store.last_known_good(&watch.name, &collectors)?;
216	    let history = store.recent_metrics(&watch.name, INCIDENT_HISTORY_RUNS)?;
217	    let evidence = Evidence {
218	        watch: &watch.name,
219	        reason,
220	        since,
221	        run,
222	        stats,
223	        history: &history,
224	        current: &current,
225	        last_good: last_good.as_ref(),
226	    };
227	    incident::create(&paths.incidents_dir, &evidence, created)
228	}
