230	fn register_investigation(paths: &Paths, watch: &str) -> Option<investigation::Registration> {
231	    let result =
232	        probe::enumerate().and_then(|processes| investigation::register(paths, watch, &processes));
233	    result.unwrap_or_else(|error| {
