246	/// プロセスを既知の集合と照らして分類する。
247	///
248	/// 学習してよいのは正常な回だけ。正常かどうかは条件式の成否で決まるが、その式の変数は
249	/// 分類の結果に依存する。そこで、まず学習する前提で分類し、式が成立したら（異常なら）
250	/// 何も学習しない前提でやり直す。やり直すと pending が増えるだけなので、成立したままになる
251	fn classify_processes(
252	    store: &Store,
253	    paths: &Paths,
254	    watch: &Watch,
255	    processes: &[ProcessInfo],
256	    metrics: &Variables,
257	    now: i64,
258	) -> Result<Classification> {
259	    let roots = Roots::from_env();
260	    // kuda 自身と、実行中の調査プロセス（detach されていて親子ではたどれない）
261	    let mut excluded: Vec<_> = known_set::own_root(processes).into_iter().collect();
262	    excluded.extend(investigation::running(paths, processes));
263	    let classify =
264	        |learn| known_set::classify(store, watch, processes, &excluded, &roots, now, learn);
265	    let classification = classify(true)?;
266	    if classification.learned == 0 {
267	        return Ok(classification);
268	    }
269	    let mut variables = metrics.clone();
270	    variables.extend(classification.metrics.clone());
271	    if trigger_matches(watch, &variables) {
272	        return classify(false);
273	    }
274	    Ok(classification)
275	}
