278	fn fire(
279	    store: &mut Store,
280	    paths: &Paths,
281	    watch: &Watch,
282	    run: &ProbeRun,
283	    stats: &[SeriesStats],
284	    since: i64,
285	    reason: &str,
286	    pending: &[String],
287	) -> Result<()> {
288	    let incident = build_incident(store, paths, watch, run, stats, since, reason)?;
289	    log::warn!(
290	        "{}: fired ({reason}); incident {}",
291	        watch.name,
292	        incident.dir.display()
293	    );
294	    // 事件に含めた分は報告済みにする。同じプロセスでは、クールダウンが明けても再発火しない
295	    store.mark_reported(&watch.name, pending)?;
296	    if watch.diagnose.is_some() {
297	        detach::spawn_diagnose(&watch.name, &incident.dir)?;
298	    }
299	    Ok(())
300	}
