302	fn write_recovery(paths: &Paths, watch: &str, since: i64, now: i64) -> Result<()> {
303	    let dir = paths.reports_dir.join(watch);
304	    create_private_dir(&dir)?;
305	    let stamp = Local::now().format("%Y%m%d-%H%M%S");
306	    let path = dir.join(format!("{stamp}-recovered.md"));
307	    let text = format!(
308	        "# 回復: {watch}\n\n- 発生開始: {}\n- 回復確認: {}\n",
309	        format_time(since),
310	        format_time(now)
311	    );
312	    std::fs::write(&path, text).with_context(|| format!("failed to write {}", path.display()))?;
313	    log::info!("{watch}: recovered; {}", path.display());
314	    Ok(())
315	}
