317	pub fn snapshot(config: &Config, paths: &Paths, force: bool, only: Option<&str>) -> Result<()> {
318	    if let Some(name) = only {
319	        config.watch(name)?;
320	    }
321	    let store = Store::open(&paths.db_file())?;
322	    let mut failed = 0;
323	    let selected = config
324	        .watches
325	        .iter()
326	        .filter(|watch| only.is_none_or(|name| name == watch.name));
327	    for watch in selected {
328	        let collectors = &watch.baseline.snapshot_collectors;
329	        if collectors.is_empty() {
330	            println!("{}: no snapshot_collectors configured", watch.name);
331	            continue;
332	        }
333	        // check のロックは取らない。check と並行してよいよう、スナップショットの記録以外は
334	        // 書かない。ここで読んだ状態を save_state で書き戻すと、収集中に check が保存した状態を巻き戻す
335	        let state = store.load_state(&watch.name)?;
336	        let now = now();
337	        if !force && !is_snapshot_due(&state, now, watch.baseline.snapshot_interval) {
338	            println!(
339	                "{}: not due yet (snapshot_interval, or the retry interval after a failure)",
340	                watch.name
341	            );
342	            continue;
343	        }
344	        let snapshot = take_snapshot(&store, watch, now)?;
345	        print_collectors(&watch.name, &snapshot);
346	        failed += collector::failed_collectors(&snapshot).len();
347	    }
348	    if failed > 0 {
349	        bail!("{failed} collector(s) failed");
350	    }
351	    Ok(())
352	}
