354	fn print_collectors(watch: &str, snapshot: &Value) {
355	    let collectors = snapshot["collectors"].as_object().into_iter().flatten();
356	    for (name, result) in collectors {
357	        match result["error"].as_str() {
358	            None => println!("{watch}: {name}: ok"),
359	            Some(error) => println!("{watch}: {name}: FAILED: {error}"),
360	        }
361	    }
362	}
