364	pub struct DiagnoseOptions {
365	    pub watch: String,
366	    pub dry_run: bool,
367	    pub backend: Option<String>,
368	    pub incident: Option<PathBuf>,
369	    pub notify: bool,
370	}
371	
372	pub fn diagnose(config: &Config, paths: &Paths, options: DiagnoseOptions) -> Result<()> {
373	    let watch = config.watch(&options.watch)?;
374	    let override_kind = options
375	        .backend
376	        .as_deref()
377	        .map(BackendKind::parse)
378	        .transpose()?;
379	
380	    let incident = match &options.incident {
381	        Some(dir) => incident::load(dir)?,
382	        None => manual_incident(paths, watch)?,
383	    };
384	    // 別の watch の事件を、この watch の設定やロックのまま調べない
385	    ensure!(
386	        incident.watch == watch.name,
387	        "incident {} belongs to watch {:?}, not {:?}",
388	        incident.dir.display(),
389	        incident.watch,
390	        watch.name
391	    );
392	    println!("incident: {}", incident.dir.display());
393	    if options.dry_run {
394	        return Ok(());
395	    }
396	
397	    let diagnose = watch
398	        .diagnose
399	        .as_ref()
400	        .with_context(|| format!("watch {} has no [watch.diagnose]", watch.name))?;
401	    let lock_path = paths
402	        .lock_dir
403	        .join(format!("kuda-diagnose-{}.lock", watch.name));
404	    if !lock::hold_until_exit(&lock_path)? {
405	        log::info!("{}: an investigation is already running", watch.name);
406	        println!("an investigation for {} is already running", watch.name);
407	        return Ok(());
408	    }
409	    // 調査の間だけ記録し、check のプロセス監視が調査プロセスを未知として数えないようにする
410	    let _registration = register_investigation(paths, &watch.name);
411	    let notify = options.notify && config.general.notify;
412	    if notify {
413	        notify::send(&Event::Started { watch: &watch.name });
414	    }
415	    let result = diagnosis::investigate(config, paths, diagnose, &incident, override_kind);
416	    if notify {
417	        let failed_report = diagnosis::report_path(paths, &incident).ok();
418	        notify::send(&match &result {
419	            Ok(report) => Event::Finished {
420	                watch: &watch.name,
421	                report,
422	            },
423	            Err(_) => Event::Failed {
424	                watch: &watch.name,
425	                report: failed_report.as_deref().filter(|path| path.is_file()),
426	            },
427	        });
428	    }
429	    let report = result?;
430	    log::info!("{}: report {}", watch.name, report.display());
431	    println!("report: {}", report.display());
432	    Ok(())
433	}
