435	/// 手動の調査用に、今の状態から事件を作る。ベースラインには記録しない
436	fn manual_incident(paths: &Paths, watch: &Watch) -> Result<Incident> {
437	    let store = Store::open(&paths.db_file())?;
438	    let now = now();
439	    let run = probe::run(&watch.probe, now);
440	    let stats = baseline::stats(&store, &watch.name, &watch.baseline, now)?;
441	    let since = store.load_state(&watch.name)?.trigger.since.unwrap_or(now);
442	    build_incident(&store, paths, watch, &run, &stats, since, "手動実行")
443	}
