459	/// 最後の取得時刻と、そのとき失敗した collector があったか。
460	/// 成否の記録が無いとき（版 3 へ上げた直後）は、失敗とは言い切らない
461	fn snapshot_status(state: &WatchState) -> String {
462	    let Some(last) = state.last_snapshot else {
463	        return "none".to_string();
464	    };
465	    match state.last_snapshot_complete {
466	        Some(true) => format_time(last),
467	        Some(false) => format!(
468	            "{} (some collectors failed; last complete: {})",
469	            format_time(last),
470	            state
471	                .last_complete_snapshot
472	                .map_or("none".to_string(), format_time)
473	        ),
474	        None => format!("{} (no complete snapshot recorded yet)", format_time(last)),
475	    }
476	}
