479	    let last_probe = state.last_probe.map_or("never".to_string(), format_time);
480	    println!("  last probe: {last_probe}");
481	    println!("  samples: {}", store.sample_count(&watch.name)?);
482	    for result in store.last_results(&watch.name)? {
483	        let outcome = match (&result.error, result.rtt_ms) {
484	            (Some(error), _) => format!("FAILED: {error}"),
485	            (None, Some(rtt)) => format!("ok ({rtt:.1} ms)"),
486	            (None, None) => "ok".to_string(),
487	        };
