509	fn print_trigger_status(watch: &Watch, state: &WatchState, now: i64) {
510	    let Some(trigger) = &watch.trigger else {
511	        println!("  trigger: none");
512	        return;
513	    };
514	    let cooldown = trigger.cooldown.as_secs() as i64;
515	    let remaining = state
516	        .trigger
517	        .last_fired
518	        .map_or(0, |fired| fired + cooldown - now)
519	        .max(0);
520	    println!(
521	        "  trigger: streak {}/{}, {}, cooldown remaining {remaining}s",
522	        state.trigger.streak,
523	        trigger.consecutive,
524	        if state.trigger.active {
525	            "active"
526	        } else {
527	            "idle"
528	        },
529	    );
530	}
