532	pub fn check_config(config: &Config, paths: &Paths) -> Result<()> {
533	    let mut problems = Vec::new();
534	    for watch in &config.watches {
535	        let Some(diagnose) = &watch.diagnose else {
536	            continue;
537	        };
538	        let prompt = paths.config_dir.join(&diagnose.prompt_file);
539	        if !prompt.is_file() {
540	            problems.push(format!(
541	                "{}: prompt file not found: {}",
542	                watch.name,
543	                prompt.display()
544	            ));
545	        }
546	        for kind in std::iter::once(diagnose.backend).chain(diagnose.fallback) {
547	            if let Some(command) = backend_command(config, kind)
548	                && process::find_program(command).is_none()
549	            {
550	                problems.push(format!(
551	                    "{}: {} command not found: {command}",
552	                    watch.name,
553	                    kind.name()
554	                ));
555	            }
556	        }
557	    }
558	    if !problems.is_empty() {
559	        for problem in &problems {
560	            println!("{problem}");
561	        }
562	        bail!("{} problem(s) found", problems.len());
563	    }
564	    println!("config ok: {} watch(es)", config.watches.len());
565	    Ok(())
566	}
