569	fn backend_command(config: &Config, kind: BackendKind) -> Option<&str> {
570	    match kind {
571	        BackendKind::ClaudeCode => Some(&config.backends.claude_code.as_ref()?.command),
572	        BackendKind::Codex => Some(&config.backends.codex.as_ref()?.command),
573	        BackendKind::Local => None,
574	    }
575	}
