577	pub fn check_backends(config: &Config) -> Result<()> {
578	    for kind in BackendKind::ALL {
579	        let Ok(backend) = diagnosis::backend(config, kind) else {
580	            println!("{}: not configured", kind.name());
581	            continue;
582	        };
583	        match backend.available() {
584	            Ok(detail) => println!("{}: available ({detail})", kind.name()),
585	            Err(reason) => println!("{}: unavailable: {reason}", kind.name()),
586	        }
587	    }
