43	/// 版 3: 取得履歴（snapshots）と比較基準を分ける。比較基準は collector ごとに
44	/// 最後に成功したデータを持ち、失敗した取得で置き換えない。
45	/// 既存の履歴からは collector ごとに最後の成功を拾って基準にする。全 collector が
46	/// 成功した最後の取得時刻は分からないので空にし、次の取得を再試行の間隔で行う
47	const KNOWN_GOOD: &str = "
48	    CREATE TABLE known_good (
49	        watch TEXT NOT NULL,
50	        collector TEXT NOT NULL,
51	        ts INTEGER NOT NULL,
52	        data TEXT NOT NULL,
53	        PRIMARY KEY (watch, collector)
54	    ) WITHOUT ROWID;
55	    -- 壊れた行で DB を開けなくならないよう、形の合わない行は読まずに飛ばす。
56	    -- SQLite は AND を左から評価するとは限らないので、CASE で順序を決める
57	    INSERT INTO known_good (watch, collector, ts, data)
58	        SELECT s.watch, c.key, MAX(s.ts), c.value -> '$.data'
59	        FROM snapshots AS s,
60	             json_each(
61	                 CASE WHEN NOT json_valid(s.data) THEN '{}'
62	                      WHEN json_type(s.data, '$.collectors') = 'object' THEN s.data
63	                      ELSE '{}' END,
64	                 '$.collectors'
65	             ) AS c
66	        WHERE CASE WHEN c.type = 'object'
67	                   THEN json_type(c.value, '$.ok') = 'true'
68	                        AND json_type(c.value, '$.data') IS NOT NULL
69	                   ELSE 0 END
70	        GROUP BY s.watch, c.key;
71	    ALTER TABLE watch_state ADD COLUMN last_complete_snapshot INTEGER;
72	    ALTER TABLE watch_state ADD COLUMN last_snapshot_complete INTEGER;
73	";
