228	    /// `path` はエラーメッセージに出すためのもの
229	    fn init(conn: Connection, path: &Path) -> Result<Self> {
230	        // 調査プロセスと次の check が同時に開いても待ち合わせで済むようにする
231	        conn.busy_timeout(Duration::from_secs(10))?;
232	        conn.pragma_update(None, "journal_mode", "WAL")?;
233	        let mut store = Self { conn };
234	        store.migrate(path)?;
235	        Ok(store)
236	    }
