243	    /// `user_version` の版から最新版まで 1 段ずつ上げる。
244	    /// 同時に開いた別プロセスと二重に適用しないよう、版の確認と適用を同じ書き込みトランザクションで行う。
245	    /// 新しい kuda が上げた DB は読み方が分からないので開かない（ダウングレードは非対応）
246	    fn migrate(&mut self, path: &Path) -> Result<()> {
247	        // 最新版なら書き込みロックを取らずに済ませる
248	        if Self::version(&self.conn)? == MIGRATIONS.len() {
249	            return Ok(());
250	        }
251	        loop {
252	            let tx = self
253	                .conn
254	                .transaction_with_behavior(TransactionBehavior::Immediate)?;
255	            let version = Self::version(&tx)?;
256	            if version == MIGRATIONS.len() {
257	                return Ok(());
258	            }
259	            let Some(migration) = MIGRATIONS.get(version) else {
260	                bail!(
261	                    "{} has schema version {version}, but this kuda supports up to {}. \
262	                     Update kuda, or move the database aside to start over",
263	                    path.display(),
264	                    MIGRATIONS.len()
265	                );
266	            };
267	            tx.execute_batch(migration).with_context(|| {
268	                format!(
269	                    "failed to migrate {} to schema version {}",
270	                    path.display(),
271	                    version + 1
272	                )
273	            })?;
274	            tx.pragma_update(None, "user_version", (version + 1) as i64)?;
275	            tx.commit()?;
276	        }
277	    }
