384	    /// (bin, 件数) を bin の昇順で返す。`bucket` は (集計方式, 時間帯) で、
385	    /// None なら集計方式も時間帯も問わず全体を合算する
386	    pub fn hist(
387	        &self,
388	        watch: &str,
389	        series: &str,
390	        bucket: Option<(&str, i64)>,
391	    ) -> Result<Vec<(i64, u64)>> {
392	        // 時間帯を指定するときは主キーの先頭 4 列で引けるよう、条件を分けた別のクエリにする
393	        let mut statement;
394	        let rows = match bucket {
395	            Some((aggregate_by, bucket)) => {
396	                statement = self.conn.prepare_cached(
397	                    "SELECT bin, SUM(count) FROM baseline_hist
398	                     WHERE watch = ?1 AND aggregate_by = ?2 AND series = ?3 AND bucket = ?4
399	                     GROUP BY bin ORDER BY bin",
400	                )?;
401	                statement.query(params![watch, aggregate_by, series, bucket])?
402	            }
403	            None => {
404	                statement = self.conn.prepare_cached(
405	                    "SELECT bin, SUM(count) FROM baseline_hist
406	                     WHERE watch = ?1 AND series = ?2
407	                     GROUP BY bin ORDER BY bin",
408	                )?;
409	                statement.query(params![watch, series])?
410	            }
411	        };
412	        Ok(rows
413	            .mapped(|row| Ok((row.get(0)?, row.get::<_, i64>(1)? as u64)))
414	            .collect::<rusqlite::Result<_>>()?)
415	    }
