439	    /// 保持期間内の probe の 1 時間あたりの回数。間に止まっていた時間も含めて均すので、実際の間隔より少なめに出る
440	    pub fn probes_per_hour(&self, watch: &str) -> Result<f64> {
441	        let (count, first, last): (i64, Option<i64>, Option<i64>) = self.conn.query_row(
442	            "SELECT COUNT(DISTINCT ts), MIN(ts), MAX(ts) FROM metrics WHERE watch = ?1",
443	            params![watch],
444	            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
445	        )?;
446	        let hours = match (first, last) {
447	            (Some(first), Some(last)) => ((last - first) as f64 / 3600.0).max(1.0),
448	            _ => return Ok(0.0),
449	        };
450	        Ok(count as f64 / hours)
451	    }
