473	    /// 正常時に取得したスナップショットを記録する。取得履歴には失敗した collector も
474	    /// そのまま残し、新しい `keep` 件だけを残す。比較基準は成功した collector の分だけを
475	    /// 置き換え、失敗した collector は前回までの成功データを使い続ける。
476	    /// 全 collector が成功したときだけ、取得時刻を `last_complete_snapshot` にも記録する
477	    pub fn record_snapshot(&self, watch: &str, ts: i64, snapshot: &Value, keep: u32) -> Result<()> {
478	        let tx = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
479	        tx.execute(
480	            "INSERT INTO snapshots (watch, ts, data) VALUES (?1, ?2, ?3)",
481	            params![watch, ts, snapshot.to_string()],
482	        )?;
483	        tx.execute(
484	            "DELETE FROM snapshots WHERE watch = ?1 AND rowid NOT IN (
485	                 SELECT rowid FROM snapshots WHERE watch = ?1
486	                 ORDER BY ts DESC, rowid DESC LIMIT ?2
487	             )",
488	            params![watch, keep],
489	        )?;
490	        let mut complete = true;
491	        for (name, result) in snapshot["collectors"].as_object().into_iter().flatten() {
492	            if result["ok"] != Value::Bool(true) {
493	                complete = false;
494	                continue;
495	            }
496	            // check と snapshot が並行したとき、収集開始の早い側が後から完了しても戻さない
497	            tx.execute(
498	                "INSERT INTO known_good (watch, collector, ts, data) VALUES (?1, ?2, ?3, ?4)
499	                 ON CONFLICT (watch, collector) DO UPDATE SET ts = excluded.ts, data = excluded.data
500	                 WHERE excluded.ts >= known_good.ts",
501	                params![watch, name, ts, result["data"].to_string()],
502	            )?;
503	        }
504	        Self::update_last_snapshot(&tx, watch, ts, complete)?;
505	        tx.commit()?;
506	        Ok(())
507	    }
508	
509	    /// `collectors` それぞれの最後の成功データをまとめた、比較基準のスナップショット。
510	    /// collector ごとに取得時刻が異なるので、時刻は各 collector の `taken_at` に持つ。
511	    /// どれも成功したことがなければ None
512	    pub fn last_known_good(&self, watch: &str, collectors: &[String]) -> Result<Option<Value>> {
513	        let mut statement = self
514	            .conn
515	            .prepare("SELECT ts, data FROM known_good WHERE watch = ?1 AND collector = ?2")?;
516	        let mut merged = serde_json::Map::new();
517	        for name in collectors {
518	            let row: Option<(i64, String)> = statement
519	                .query_row(params![watch, name], |row| Ok((row.get(0)?, row.get(1)?)))
520	                .optional()?;
521	            if let Some((ts, data)) = row {
522	                let data: Value = serde_json::from_str(&data)?;
523	                merged.insert(
524	                    name.clone(),
525	                    json!({ "ok": true, "taken_at": ts, "data": data }),
526	                );
527	            }
528	        }
529	        Ok((!merged.is_empty()).then(|| json!({ "collectors": merged })))
530	    }
