559	    /// last_snapshot・last_snapshot_complete と、`complete` なら last_complete_snapshot だけを
560	    /// 更新する。check と snapshot のどちらからも呼ばれるので、他の列は読み込んだ時点の値で
561	    /// 上書きしない。後から完了した側の収集開始が早いこともあるので、時刻は戻さない。
562	    /// 同じ秒の取得が重なったら、どちらかが失敗していれば失敗とする
563	    fn update_last_snapshot(conn: &Connection, watch: &str, ts: i64, complete: bool) -> Result<()> {
564	        // SET の右辺の列名は、どれも更新前の値を指す
565	        conn.execute(
566	            "INSERT INTO watch_state
567	                 (watch, last_snapshot, last_complete_snapshot, last_snapshot_complete, streak, active)
568	             VALUES (?1, ?2, ?3, ?4, 0, 0)
569	             ON CONFLICT (watch) DO UPDATE SET
570	                 last_snapshot =
571	                     max(coalesce(last_snapshot, excluded.last_snapshot), excluded.last_snapshot),
572	                 last_complete_snapshot = max(
573	                     coalesce(last_complete_snapshot, excluded.last_complete_snapshot),
574	                     coalesce(excluded.last_complete_snapshot, last_complete_snapshot)
575	                 ),
576	                 last_snapshot_complete = CASE
577	                     WHEN last_snapshot IS NULL OR excluded.last_snapshot > last_snapshot
578	                         THEN excluded.last_snapshot_complete
579	                     WHEN excluded.last_snapshot = last_snapshot
580	                         THEN last_snapshot_complete AND excluded.last_snapshot_complete
581	                     ELSE last_snapshot_complete
582	                 END",
583	            params![watch, ts, complete.then_some(ts), complete],
584	        )?;
585	        Ok(())
586	    }
