313	fn optional_duration<'de, D: Deserializer<'de>>(
314	    deserializer: D,
315	) -> Result<Option<Duration>, D::Error> {
316	    let text = String::deserialize(deserializer)?;
317	    parse_duration(&text)
318	        .map(Some)
319	        .map_err(serde::de::Error::custom)
320	}
