322	/// "500ms" "3s" "5m" "6h" "7d" 形式の期間を解釈する
323	pub fn parse_duration(text: &str) -> std::result::Result<Duration, String> {
324	    let error = || format!("invalid duration: {text:?} (expected e.g. 500ms, 3s, 5m, 6h, 7d)");
325	    let split = text.find(|c: char| !c.is_ascii_digit()).ok_or_else(error)?;
326	    let (number, unit) = text.split_at(split);
327	    let number: u64 = number.parse().map_err(|_| error())?;
328	    let millis = match unit {
329	        "ms" => Some(1),
330	        "s" => Some(1000),
331	        "m" => Some(60_000),
332	        "h" => Some(3_600_000),
333	        "d" => Some(86_400_000),
334	        _ => None,
335	    };
336	    millis
337	        .and_then(|unit| number.checked_mul(unit))
338	        .map(Duration::from_millis)
339	        .ok_or_else(error)
340	}
