342	impl Config {
343	    pub fn load(path: &Path) -> Result<Self> {
344	        let text = std::fs::read_to_string(path)
345	            .with_context(|| format!("failed to read {}", path.display()))?;
346	        Self::parse(&text).with_context(|| format!("invalid config: {}", path.display()))
347	    }
348	
349	    fn parse(text: &str) -> Result<Self> {
350	        let config: Self = toml::from_str(text)?;
351	        config.validate()?;
352	        Ok(config)
353	    }
354	
355	    pub fn watch(&self, name: &str) -> Result<&Watch> {
356	        self.watches
357	            .iter()
358	            .find(|watch| watch.name == name)
359	            .with_context(|| format!("no such watch: {name}"))
360	    }
361	
362	    fn backend_defined(&self, kind: BackendKind) -> bool {
363	        match kind {
364	            BackendKind::ClaudeCode => self.backends.claude_code.is_some(),
365	            BackendKind::Codex => self.backends.codex.is_some(),
366	            BackendKind::Local => self.backends.local.is_some(),
367	        }
368	    }
369	
370	    fn validate(&self) -> Result<()> {
371	        let mut names = HashSet::new();
372	        for watch in &self.watches {
373	            // ディレクトリ名と systemd のユニット名にそのまま使うので文字種を絞る
374	            ensure!(
375	                is_safe_name(&watch.name),
376	                "watch name must be [A-Za-z0-9_-]+: {:?}",
377	                watch.name
378	            );
379	            ensure!(
380	                names.insert(&watch.name),
381	                "duplicate watch name: {}",
382	                watch.name
383	            );
384	            self.validate_watch(watch)
385	                .with_context(|| format!("watch {:?}", watch.name))?;
386	        }
387	        Ok(())
388	    }
389	
390	    fn validate_watch(&self, watch: &Watch) -> Result<()> {
391	        watch.probe.validate()?;
392	        if watch.probe.kind == ProbeKind::Process {
393	            ensure!(
394	                watch.baseline.learn_for.is_some(),
395	                "process probe needs `learn_for` in [watch.baseline]"
396	            );
397	        } else {
398	            ensure!(
399	                watch.baseline.learn_for.is_none(),
400	                "`learn_for` is only for kind = \"process\""
401	            );
402	        }
403	        if let Some(trigger) = &watch.trigger {
404	            ensure!(trigger.consecutive >= 1, "consecutive must be at least 1");
405	            // 式の変数は probe の種類で決まるので、パースではなくここで照合する
406	            let available = trigger::variables_for(watch.probe.kind);
407	            for name in trigger.when.variables() {
408	                ensure!(
409	                    available.contains(&name),
410	                    "unknown variable: {name} (available: {})",
411	                    available.join(", ")
412	                );
413	            }
414	        }
415	        if let Some(diagnose) = &watch.diagnose {
416	            for kind in std::iter::once(diagnose.backend).chain(diagnose.fallback) {
417	                ensure!(
418	                    self.backend_defined(kind),
419	                    "backend {} is not configured in [backends]",
420	                    kind.name()
421	                );
422	            }
423	        }
424	        Ok(())
425	    }
426	}
