428	impl Probe {
429	    fn validate(&self) -> Result<()> {
430	        if self.kind == ProbeKind::Process {
431	            ensure!(self.targets.is_empty(), "process probe takes no `targets`");
432	            ensure!(self.command.is_empty(), "process probe takes no `command`");
433	            return Ok(());
434	        }
435	        ensure!(
436	            self.expected.is_empty() && self.ignore.is_empty(),
437	            "`expected` and `ignore` are only for kind = \"process\""
438	        );
439	        if self.kind == ProbeKind::Command {
440	            ensure!(!self.command.is_empty(), "command probe needs `command`");
441	            ensure!(self.targets.is_empty(), "command probe takes no `targets`");
442	            return Ok(());
443	        }
444	        ensure!(!self.targets.is_empty(), "probe needs `targets`");
445	        for target in &self.targets {
446	            match self.kind {
447	                ProbeKind::Tcp => {
448	                    let has_port = target
449	                        .rsplit_once(':')
450	                        .is_some_and(|(_, port)| port.parse::<u16>().is_ok());
451	                    if !has_port && target != "gateway" {
452	                        bail!("tcp target needs a port: {target}");
453	                    }
454	                }
455	                ProbeKind::Http => {
456	                    if !target.starts_with("http://") && !target.starts_with("https://") {
457	                        bail!("http target must be a URL: {target}");
458	                    }
459	                }
460	                ProbeKind::Icmp | ProbeKind::Dns | ProbeKind::Command | ProbeKind::Process => {}
461	            }
462	        }
463	        Ok(())
464	    }
465	}
