60	pub struct ProbeRun {
61	    pub ts: i64,
62	    pub results: Vec<TargetResult>,
63	    /// kind = "process" の列挙結果。他の kind では None
64	    pub processes: Option<Vec<ProcessInfo>>,
65	}
