67	impl ProbeRun {
68	    /// 条件式の変数になる集計値。値の無い指標はキーごと省く
69	    pub fn metrics(&self) -> Variables {
70	        let mut metrics = Variables::new();
71	        let failed = self.results.iter().filter(|r| !r.ok).count();
72	        metrics.insert(
73	            "loss".to_string(),
74	            failed as f64 / self.results.len().max(1) as f64,
75	        );
76	
77	        let mut rtts: Vec<f64> = self.results.iter().filter_map(|r| r.rtt_ms).collect();
78	        rtts.sort_by(f64::total_cmp);
79	        if let Some(max) = rtts.last() {
80	            metrics.insert("rtt_max".to_string(), *max);
81	            metrics.insert("rtt_p50".to_string(), percentile(&rtts, 0.50));
82	            metrics.insert("rtt_p95".to_string(), percentile(&rtts, 0.95));
83	        }
84	        if let Some(value) = self.results.iter().find_map(|r| r.value) {
85	            metrics.insert("value".to_string(), value);
86	        }
87	        metrics
88	    }
89	}
90	
91	/// ソート済みの値から nearest-rank 法で百分位数を取る
92	fn percentile(sorted: &[f64], fraction: f64) -> f64 {
93	    let rank = (sorted.len() as f64 * fraction).ceil() as usize;
94	    sorted[rank.clamp(1, sorted.len()) - 1]
95	}
96	
97	fn run_target(probe: &Probe, target: &str, gateway: Option<IpAddr>) -> Result<Sample, String> {
98	    match probe.kind {
99	        ProbeKind::Tcp => tcp::check(target, gateway, probe.timeout),
100	        ProbeKind::Icmp => {
101	            let host = expand_gateway(target, gateway)?;
102	            icmp::check(&host, probe.timeout)
103	        }
104	        ProbeKind::Dns => dns::check(target, probe.server.as_deref(), probe.timeout),
105	        ProbeKind::Http => http::check(target, probe.expect_status, probe.timeout),
106	        ProbeKind::Command => command::check(&probe.command, probe.timeout),
107	        // run が先に分岐するので、ここには来ない
108	        ProbeKind::Process => Err("process probe has no targets".to_string()),
109	    }
110	}
111	
112	fn expand_gateway(target: &str, gateway: Option<IpAddr>) -> Result<String, String> {
113	    if target != "gateway" {
114	        return Ok(target.to_string());
115	    }
116	    gateway
117	        .map(|ip| ip.to_string())
118	        .ok_or_else(|| "no default gateway".to_string())
119	}
120	
121	/// 全ターゲットを並列に試す。所要時間は最も遅いターゲットで決まる
122	pub fn run(probe: &Probe, ts: i64) -> ProbeRun {
123	    if probe.kind == ProbeKind::Process {
124	        return run_process(ts);
125	    }
126	    let gateway = collector::default_gateway();
127	    let targets = match probe.kind {
128	        ProbeKind::Command => probe.command[..1].to_vec(),
129	        _ => probe.targets.clone(),
130	    };
131	    let results = std::thread::scope(|scope| {
132	        let handles: Vec<_> = targets
133	            .iter()
134	            .map(|target| {
135	                scope.spawn(move || TargetResult::new(target, run_target(probe, target, gateway)))
136	            })
137	            .collect();
138	        handles
139	            .into_iter()
140	            .zip(&targets)
141	            .map(|(handle, target)| {
142	                handle.join().unwrap_or_else(|_| {
143	                    TargetResult::new(target, Err("probe thread panicked".to_string()))
144	                })
145	            })
146	            .collect()
147	    });
148	    ProbeRun {
149	        ts,
150	        results,
151	        processes: None,
152	    }
153	}
154	
155	/// 列挙の成否を、target = "processes" の 1 件で表す
156	fn run_process(ts: i64) -> ProbeRun {
157	    let (result, processes) = match process::enumerate() {
158	        Ok(processes) => (Ok(Sample::default()), Some(processes)),
159	        Err(e) => (Err(format!("{e:#}")), None),
160	    };
161	    ProbeRun {
162	        ts,
163	        results: vec![TargetResult::new("processes", result)],
164	        processes,
165	    }
166	}
