1	//! 発火条件の式と、連続回数・クールダウンの判定。
2	//!
3	//! 式は `loss >= 0.5 || rtt_p50 > baseline.rtt_p95 * 2` のような形で、
4	//! 値が無い変数（データ不足のベースラインや、全滅時の RTT）を含む比較は
5	//! 「不明」になる。最終結果が不明なら発火しない。
6	
7	use crate::config::{ProbeKind, Trigger};
8	use serde::Deserialize;
9	use std::collections::BTreeMap;
10	
11	/// probe の種類ごとに、条件式で使える変数。
12	///
13	/// 式のパースでは検査しない。変数は probe の種類で決まり、パースの時点では
14	/// どの probe の式か分からないので、`Config::validate_watch` が照合する。
15	/// 網羅的に match しているのは、probe の種類を足したときに許可リストの決め忘れを防ぐため。
16	pub fn variables_for(kind: ProbeKind) -> &'static [&'static str] {
17	    match kind {
18	        ProbeKind::Tcp
19	        | ProbeKind::Icmp
20	        | ProbeKind::Dns
21	        | ProbeKind::Http
22	        | ProbeKind::Command => &[
23	            "loss",
24	            "rtt_p50",
25	            "rtt_p95",
26	            "rtt_max",
27	            "value",
28	            "baseline.rtt_p50",
29	            "baseline.rtt_p95",
30	            "baseline.loss_p50",
31	            "baseline.loss_p95",
32	            "baseline.value_p50",
33	            "baseline.value_p95",
34	        ],
35	        // baseline.* は無い。時間帯の統計ではなく、既知の集合と比べる
36	        ProbeKind::Process => &[
37	            "loss",
38	            "unknown",
39	            "unknown_user_writable",
40	            "masquerade",
41	            "missing",
42	            "process_count",
43	        ],
44	    }
45	}
