91	enum Token {
92	    Number(f64),
93	    Ident(String),
94	    Op(&'static str),
95	}
96	
97	const OPERATORS: [&str; 15] = [
98	    "||", "&&", ">=", "<=", "==", "!=", ">", "<", "!", "+", "-", "*", "/", "(", ")",
99	];
100	
101	fn tokenize(source: &str) -> Result<Vec<Token>, String> {
102	    let mut tokens = Vec::new();
103	    let mut rest = source.trim_start();
104	    while let Some(c) = rest.chars().next() {
105	        if let Some(op) = OPERATORS.iter().find(|op| rest.starts_with(**op)) {
106	            tokens.push(Token::Op(op));
107	            rest = &rest[op.len()..];
108	        } else if c.is_ascii_digit() {
109	            let end = rest
110	                .find(|c: char| !c.is_ascii_digit() && c != '.')
111	                .unwrap_or(rest.len());
112	            let number = rest[..end]
113	                .parse()
114	                .map_err(|_| format!("invalid number: {}", &rest[..end]))?;
115	            tokens.push(Token::Number(number));
116	            rest = &rest[end..];
117	        } else if c.is_ascii_alphabetic() || c == '_' {
118	            let end = rest
119	                .find(|c: char| !c.is_ascii_alphanumeric() && c != '_' && c != '.')
120	                .unwrap_or(rest.len());
121	            tokens.push(Token::Ident(rest[..end].to_string()));
122	            rest = &rest[end..];
123	        } else {
124	            return Err(format!("unexpected character: {c:?}"));
125	        }
126	        rest = rest.trim_start();
127	    }
128	    Ok(tokens)
129	}
130	
131	struct Parser {
132	    tokens: Vec<Token>,
133	    pos: usize,
134	}
135	
136	impl Parser {
137	    fn eat(&mut self, op: &str) -> bool {
138	        let matched = matches!(self.tokens.get(self.pos), Some(Token::Op(o)) if *o == op);
139	        if matched {
140	            self.pos += 1;
141	        }
142	        matched
143	    }
144	
145	    fn or(&mut self) -> Result<Cond, String> {
146	        let mut left = self.and()?;
147	        while self.eat("||") {
148	            left = Cond::Or(Box::new(left), Box::new(self.and()?));
149	        }
150	        Ok(left)
151	    }
152	
153	    fn and(&mut self) -> Result<Cond, String> {
154	        let mut left = self.unary()?;
155	        while self.eat("&&") {
156	            left = Cond::And(Box::new(left), Box::new(self.unary()?));
157	        }
158	        Ok(left)
159	    }
160	
161	    fn unary(&mut self) -> Result<Cond, String> {
162	        if self.eat("!") {
163	            return Ok(Cond::Not(Box::new(self.unary()?)));
164	        }
165	        // "(" は論理式の括弧か算術の括弧か読むまで分からないので、比較を先に試す
166	        let start = self.pos;
167	        match self.comparison() {
168	            Ok(cond) => Ok(cond),
169	            Err(error) => {
170	                self.pos = start;
171	                if !self.eat("(") {
172	                    return Err(error);
173	                }
174	                let inner = self.or()?;
175	                if !self.eat(")") {
176	                    return Err("expected ')'".to_string());
177	                }
178	                Ok(inner)
179	            }
180	        }
181	    }
182	
183	    fn comparison(&mut self) -> Result<Cond, String> {
184	        let left = self.sum()?;
185	        let ops = [
186	            (">=", CmpOp::Ge),
187	            ("<=", CmpOp::Le),
188	            ("==", CmpOp::Eq),
189	            ("!=", CmpOp::Ne),
190	            (">", CmpOp::Gt),
191	            ("<", CmpOp::Lt),
192	        ];
193	        for (text, op) in ops {
194	            if self.eat(text) {
195	                return Ok(Cond::Cmp(op, left, self.sum()?));
196	            }
197	        }
198	        Err("expected a comparison such as `loss >= 0.5`".to_string())
199	    }
200	
201	    fn sum(&mut self) -> Result<Num, String> {
202	        let mut left = self.product()?;
203	        loop {
204	            let op = if self.eat("+") {
205	                ArithOp::Add
206	            } else if self.eat("-") {
207	                ArithOp::Sub
208	            } else {
209	                return Ok(left);
210	            };
211	            left = Num::Arith(op, Box::new(left), Box::new(self.product()?));
212	        }
213	    }
214	
215	    fn product(&mut self) -> Result<Num, String> {
216	        let mut left = self.atom()?;
217	        loop {
218	            let op = if self.eat("*") {
219	                ArithOp::Mul
220	            } else if self.eat("/") {
221	                ArithOp::Div
222	            } else {
223	                return Ok(left);
224	            };
225	            left = Num::Arith(op, Box::new(left), Box::new(self.atom()?));
226	        }
227	    }
228	
229	    fn atom(&mut self) -> Result<Num, String> {
230	        if self.eat("-") {
231	            return Ok(Num::Neg(Box::new(self.atom()?)));
232	        }
233	        if self.eat("(") {
234	            let inner = self.sum()?;
235	            if !self.eat(")") {
236	                return Err("expected ')'".to_string());
237	            }
238	            return Ok(inner);
239	        }
240	        let token = self.tokens.get(self.pos).cloned();
241	        self.pos += 1;
242	        match token {
243	            Some(Token::Number(n)) => Ok(Num::Literal(n)),
244	            Some(Token::Ident(name)) => Ok(Num::Var(name)),
245	            Some(Token::Op(op)) => Err(format!("unexpected {op:?}")),
246	            None => Err("unexpected end of expression".to_string()),
247	        }
248	    }
249	}
250	
251	impl TryFrom<String> for Expr {
252	    type Error = String;
253	
254	    fn try_from(source: String) -> Result<Self, String> {
255	        let tokens = tokenize(&source)?;
256	        let mut parser = Parser { tokens, pos: 0 };
257	        let root = parser.or()?;
258	        if parser.pos != parser.tokens.len() {
259	            return Err(format!(
260	                "unexpected trailing input in {source:?} at token {}",
261	                parser.pos + 1
262	            ));
263	        }
264	        Ok(Self { source, root })
265	    }
266	}
267	
268	impl Expr {
269	    pub fn source(&self) -> &str {
270	        &self.source
271	    }
272	
273	    /// 式の中で使っている変数名（出現順、重複なし）
274	    pub fn variables(&self) -> Vec<&str> {
275	        let mut names = Vec::new();
276	        self.root.collect_variables(&mut names);
277	        names
278	    }
279	
280	    /// 不明（判定材料が足りない）場合は発火させない
281	    pub fn matches(&self, vars: &Variables) -> bool {
282	        self.root.eval(vars) == Some(true)
283	    }
284	}
285	
286	impl Cond {
287	    fn collect_variables<'a>(&'a self, names: &mut Vec<&'a str>) {
288	        match self {
289	            Self::Or(a, b) | Self::And(a, b) => {
290	                a.collect_variables(names);
291	                b.collect_variables(names);
292	            }
293	            Self::Not(inner) => inner.collect_variables(names),
294	            Self::Cmp(_, a, b) => {
295	                a.collect_variables(names);
296	                b.collect_variables(names);
297	            }
298	        }
299	    }
300	
301	    fn eval(&self, vars: &Variables) -> Option<bool> {
302	        match self {
303	            Self::Or(a, b) => match (a.eval(vars), b.eval(vars)) {
304	                (Some(true), _) | (_, Some(true)) => Some(true),
305	                (Some(false), Some(false)) => Some(false),
306	                _ => None,
307	            },
308	            Self::And(a, b) => match (a.eval(vars), b.eval(vars)) {
309	                (Some(false), _) | (_, Some(false)) => Some(false),
310	                (Some(true), Some(true)) => Some(true),
311	                _ => None,
312	            },
313	            Self::Not(inner) => inner.eval(vars).map(|value| !value),
314	            Self::Cmp(op, a, b) => {
315	                let (a, b) = (a.eval(vars)?, b.eval(vars)?);
316	                Some(match op {
317	                    CmpOp::Gt => a > b,
318	                    CmpOp::Ge => a >= b,
319	                    CmpOp::Lt => a < b,
320	                    CmpOp::Le => a <= b,
321	                    CmpOp::Eq => a == b,
322	                    CmpOp::Ne => a != b,
323	                })
324	            }
325	        }
326	    }
327	}
328	
329	impl Num {
330	    fn collect_variables<'a>(&'a self, names: &mut Vec<&'a str>) {
331	        match self {
332	            Self::Literal(_) => {}
333	            Self::Var(name) => {
334	                if !names.contains(&name.as_str()) {
335	                    names.push(name);
336	                }
337	            }
338	            Self::Neg(inner) => inner.collect_variables(names),
339	            Self::Arith(_, a, b) => {
340	                a.collect_variables(names);
341	                b.collect_variables(names);
342	            }
343	        }
344	    }
345	
346	    fn eval(&self, vars: &Variables) -> Option<f64> {
347	        match self {
348	            Self::Literal(value) => Some(*value),
349	            Self::Var(name) => vars.get(name).copied(),
350	            Self::Neg(inner) => inner.eval(vars).map(|value| -value),
351	            Self::Arith(op, a, b) => {
352	                let (a, b) = (a.eval(vars)?, b.eval(vars)?);
353	                match op {
354	                    ArithOp::Add => Some(a + b),
355	                    ArithOp::Sub => Some(a - b),
356	                    ArithOp::Mul => Some(a * b),
357	                    ArithOp::Div => (b != 0.0).then(|| a / b),
358	                }
359	            }
360	        }
361	    }
362	}
