364	/// watch ごとに永続化する判定状態
365	#[derive(Debug, Clone, Default, PartialEq)]
366	pub struct TriggerState {
367	    /// 条件が連続で成立している回数
368	    pub streak: u32,
369	    /// 今回の異常の開始時刻
370	    pub since: Option<i64>,
371	    pub last_fired: Option<i64>,
372	    /// 発火済みで、まだ回復していない
373	    pub active: bool,
374	}
375	
376	#[derive(Debug, Clone, Copy, PartialEq)]
377	pub enum Outcome {
378	    Normal,
379	    /// 条件は成立しているが連続回数が足りない
380	    Pending,
381	    /// クールダウン中で発火を見送った
382	    Suppressed,
383	    Fired,
384	    Recovered,
385	}
386	
387	/// 1 回分の判定結果を状態へ反映する。時刻は Unix 秒
388	pub fn advance(state: &mut TriggerState, matched: bool, trigger: &Trigger, now: i64) -> Outcome {
389	    if !matched {
390	        let outcome = if state.active {
391	            Outcome::Recovered
392	        } else {
393	            Outcome::Normal
394	        };
395	        state.streak = 0;
396	        state.since = None;
397	        state.active = false;
398	        return outcome;
399	    }
400	
401	    state.streak += 1;
402	    state.since.get_or_insert(now);
403	    if state.streak < trigger.consecutive {
404	        return Outcome::Pending;
405	    }
406	    let cooldown = trigger.cooldown.as_secs() as i64;
407	    if state.last_fired.is_some_and(|fired| now - fired < cooldown) {
408	        return Outcome::Suppressed;
409	    }
410	    state.last_fired = Some(now);
411	    state.active = true;
412	    Outcome::Fired
413	}
