1	//! 時間帯別 p50/p95 の統計ベースライン。
2	//!
3	//! weekday_hour の 1 区画は 5 分間隔でも週に 12 サンプルしか増えないので、
4	//! metrics_retention（既定 7 日）の生データからは min_samples に届かない。
5	//! そのため対数ビンのヒストグラムとして、保持期間と無関係に蓄積する。
6	//! 百分位数の誤差はビン幅の半分（約 ±2.5%）に収まる。
7	
8	use crate::config::{AggregateBy, Baseline};
9	use crate::store::{Store, V1Hist};
10	use crate::trigger::Variables;
11	use anyhow::Result;
12	use chrono::{DateTime, Datelike, Local, TimeZone, Timelike};
13	
14	/// (ヒストグラムの系列名, 元になる指標)。
15	/// 系列 rtt は probe ごとの中央値の分布で、`baseline.rtt_p95` はその 95 パーセンタイル
16	const SERIES: [(&str, &str); 3] = [("rtt", "rtt_p50"), ("loss", "loss"), ("value", "value")];
17	
18	/// 隣り合うビンの比
19	const BIN_RATIO: f64 = 1.05;
