38	/// 永続化する集計方式の名前。bucket の値は同じ方式の中でしか比べられない
39	fn aggregation_key(aggregate_by: AggregateBy) -> &'static str {
40	    match aggregate_by {
41	        AggregateBy::WeekdayHour => "weekday_hour",
42	        AggregateBy::Hour => "hour",
43	        AggregateBy::None => "none",
44	    }
45	}
46	
47	/// 集計方式がとりうる bucket の最大値
48	fn max_bucket(aggregate_by: AggregateBy) -> i64 {
49	    match aggregate_by {
50	        AggregateBy::WeekdayHour => 7 * 24 - 1,
51	        AggregateBy::Hour => 23,
52	        AggregateBy::None => 0,
53	    }
54	}
55	
56	/// 集計方式を記録していなかった版の分布を、移行後に初めて使う時点の方式で記録したものとして引き取る。
57	/// その方式で記録したとすると矛盾する分布は、時間帯別には使わず全体の統計にだけ残す
58	fn adopt_v1(store: &Store, watch: &str, aggregate_by: AggregateBy) -> Result<()> {
59	    let Some(v1) = store.v1_hist(watch)? else {
60	        return Ok(());
61	    };
62	    let plausible = v1_recorded_by(aggregate_by, &v1, store.probes_per_hour(watch)?);
63	    store.resolve_v1_hist(watch, plausible.then(|| aggregation_key(aggregate_by)))
64	}
65	
66	/// 版 1 の分布が `aggregate_by` で記録されたとみて矛盾しないか。
67	/// `probes_per_hour` は保持期間内の probe の頻度で、止まっていた時間も均すので実際より少なめに出る
68	fn v1_recorded_by(aggregate_by: AggregateBy, v1: &V1Hist, probes_per_hour: f64) -> bool {
69	    if v1.min_bucket < 0 || v1.max_bucket > max_bucket(aggregate_by) {
70	        return false;
71	    }
72	    // bucket が範囲内でも、より粗い方式でも出る値（hour の 0..=23 や none の 0）しか無いと、
73	    // 範囲からは方式を区別できない。本当に `aggregate_by` で記録したなら、その bucket に当たる
74	    // 時刻にしか記録できていない（weekday_hour で 0..=23 だけなら月曜の 1 日、bucket 0 だけなら
75	    // 0 時台の 1 時間）。その 2 倍を超えるサンプルがあれば、粗い方式で何日分も記録したとみなす。
76	    // 頻度は少なめに出るので、迷う分布は引き取らない側に倒れる
77	    let hours = match aggregate_by {
78	        AggregateBy::WeekdayHour | AggregateBy::Hour if v1.max_bucket == 0 => 1.0,
79	        AggregateBy::WeekdayHour if v1.max_bucket <= 23 => 24.0,
80	        _ => return true,
81	    };
82	    v1.samples as f64 <= 2.0 * hours * probes_per_hour
83	}
84	
85	fn bucket(aggregate_by: AggregateBy, time: DateTime<Local>) -> i64 {
86	    match aggregate_by {
87	        AggregateBy::WeekdayHour => {
88	            i64::from(time.weekday().num_days_from_monday()) * 24 + i64::from(time.hour())
89	        }
90	        AggregateBy::Hour => i64::from(time.hour()),
91	        AggregateBy::None => 0,
92	    }
93	}
94	
95	fn local_time(ts: i64) -> DateTime<Local> {
96	    Local
97	        .timestamp_opt(ts, 0)
98	        .single()
99	        .unwrap_or_else(Local::now)
100	}
101	
102	fn bin_of(value: f64) -> i64 {
103	    ((1.0 + value).ln() / BIN_RATIO.ln()).floor() as i64
104	}
105	
106	/// ビンの中央値。ビン 0 はほぼ 0 の値（loss = 0 など）なので 0 に丸める
107	fn bin_value(bin: i64) -> f64 {
108	    if bin == 0 {
109	        return 0.0;
110	    }
111	    let lower = BIN_RATIO.powi(bin as i32);
112	    (lower + lower * BIN_RATIO) / 2.0 - 1.0
113	}
114	
115	fn hist_percentile(hist: &[(i64, u64)], total: u64, fraction: f64) -> f64 {
116	    let rank = ((total as f64 * fraction).ceil() as u64).max(1);
117	    let mut seen = 0;
118	    for (bin, count) in hist {
119	        seen += count;
120	        if seen >= rank {
121	            return bin_value(*bin);
122	        }
123	    }
124	    hist.last().map_or(0.0, |(bin, _)| bin_value(*bin))
125	}
126	
127	/// 正常時の 1 回分の指標を分布へ足す
128	pub fn update(
129	    store: &Store,
130	    watch: &str,
131	    config: &Baseline,
132	    metrics: &Variables,
133	    ts: i64,
134	) -> Result<()> {
135	    adopt_v1(store, watch, config.aggregate_by)?;
136	    let aggregate_by = aggregation_key(config.aggregate_by);
137	    let bucket = bucket(config.aggregate_by, local_time(ts));
138	    for (series, metric) in SERIES {
139	        // 対数ビンで表せない負の値（command の value）は統計に入れない
140	        if let Some(value) = metrics.get(metric).filter(|value| **value >= 0.0) {
141	            store.hist_add(watch, aggregate_by, series, bucket, bin_of(*value))?;
142	        }
143	    }
144	    Ok(())
145	}
