147	/// `ts` の時間帯の統計を返す。全体でも min_samples に届かない系列は含まない。
148	/// 時間帯別には現在の aggregate_by で記録した分布だけを使い、
149	/// 全体の統計には方式を変える前の分布も含める（時間帯を問わないので意味が変わらない）
150	pub fn stats(store: &Store, watch: &str, config: &Baseline, ts: i64) -> Result<Vec<SeriesStats>> {
151	    adopt_v1(store, watch, config.aggregate_by)?;
152	    let bucket = (
153	        aggregation_key(config.aggregate_by),
154	        bucket(config.aggregate_by, local_time(ts)),
155	    );
156	    let mut result = Vec::new();
157	    for (series, _) in SERIES {
158	        let candidates = [(Source::Bucket, Some(bucket)), (Source::Overall, None)];
159	        for (source, bucket) in candidates {
160	            let hist = store.hist(watch, series, bucket)?;
161	            let samples: u64 = hist.iter().map(|(_, count)| count).sum();
162	            if samples > 0 && samples >= config.min_samples {
163	                result.push(SeriesStats {
164	                    series,
165	                    source,
166	                    samples,
167	                    p50: hist_percentile(&hist, samples, 0.50),
168	                    p95: hist_percentile(&hist, samples, 0.95),
169	                });
170	                break;
171	            }
172	        }
173	    }
174	    Ok(result)
175	}
