177	/// 条件式の `baseline.*` 変数へ展開する
178	pub fn variables(stats: &[SeriesStats]) -> Variables {
179	    let mut variables = Variables::new();
180	    for stat in stats {
181	        variables.insert(format!("baseline.{}_p50", stat.series), stat.p50);
182	        variables.insert(format!("baseline.{}_p95", stat.series), stat.p95);
183	    }
184	    variables
185	}
