1	//! プロセスの識別と分類。
2	//!
3	//! 識別・フラグ判定・除外・glob は純関数で、環境変数や実行中の OS は関数の中で読まない。
4	//! 呼び出し側が [`Os`] と [`Roots`] を渡す。こうしておくと、Windows のパス規則のテストを
5	//! Linux 上でも走らせられる。ストアを使う分類は [`classify`]。
6	
7	use crate::config::Watch;
8	use crate::probe::ProcessInfo;
9	use crate::store::{IdentityStatus, Store};
10	use crate::trigger::Variables;
11	use anyhow::Result;
12	use std::collections::{BTreeMap, HashMap, HashSet};
13	
14	/// パス規則を切り替えるための OS。実行中の OS とは限らない（テストのため）
15	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
16	pub enum Os {
17	    Windows,
18	    Linux,
19	}
20	
21	impl Os {
22	    pub fn current() -> Os {
23	        if cfg!(windows) {
24	            Os::Windows
25	        } else {
26	            Os::Linux
27	        }
28	    }
29	
30	    fn separator(self) -> char {
31	        match self {
32	            Os::Windows => '\\',
33	            Os::Linux => '/',
34	        }
35	    }
36	}
37	
38	/// 正規化の結果
39	#[derive(Debug, Clone, PartialEq, Eq)]
40	pub struct Identity {
41	    /// 識別キー。パスが取れたら正規化したパス、取れなければ `name:<小文字名>`
42	    pub key: String,
43	    /// Linux で実行ファイルが削除済み（` (deleted)`）だった。事件の証拠に載せる
44	    pub deleted: bool,
45	}
46	
47	/// パスの正規化のうち、バージョン要素の置き換えを除いた部分。フラグ判定にはこちらを使う
48	/// （`C:\Users\1.2.3\...` のような置き換えで場所の判定が変わらないように）
49	fn normalize_basic(os: Os, path: &str) -> (String, bool) {
50	    match os {
51	        Os::Windows => {
52	            let path = path.strip_prefix(r"\\?\").unwrap_or(path);
53	            (path.replace('/', "\\").to_ascii_lowercase(), false)
54	        }
55	        Os::Linux => match path.strip_suffix(" (deleted)") {
56	            Some(rest) => (rest.to_string(), true),
57	            None => (path.to_string(), false),
58	        },
59	    }
60	}
61	
62	/// パスを識別キーに正規化する（§2.2 の 1〜3）
63	pub fn normalize_path(os: Os, path: &str) -> Identity {
64	    let (path, deleted) = normalize_basic(os, path);
65	    let sep = os.separator();
66	    let key = path
67	        .split(sep)
68	        .map(|element| {
69	            if is_version_element(element) {
70	                "*"
71	            } else {
72	                element
73	            }
74	        })
75	        .collect::<Vec<_>>()
76	        .join(&sep.to_string());
77	    Identity { key, deleted }
78	}
79	
80	/// `(v|app-)?数字(.数字)+` の後に、任意で `[-+_.]` と英数字・`.` の列が続く形か。
81	/// 更新のたびに変わるディレクトリ名やファイル名を 1 つの識別キーにまとめるために使う。
82	/// `python3` や `x64` のように `.` を含まない数字は、バージョンとみなさない
83	fn is_version_element(element: &str) -> bool {
84	    let lower = element.to_ascii_lowercase();
85	    let rest = lower
86	        .strip_prefix("app-")
87	        .or_else(|| lower.strip_prefix('v'))
88	        .unwrap_or(&lower);
89	    let bytes = rest.as_bytes();
90	
91	    let digits = |from: usize| {
92	        bytes[from..]
93	            .iter()
94	            .take_while(|b| b.is_ascii_digit())
95	            .count()
96	    };
97	    let first = digits(0);
98	    if first == 0 {
99	        return false;
100	    }
101	    let mut pos = first;
102	    let mut groups = 0;
103	    // `.` の後に数字が続く限りだけ食う。`1.2.3.exe` の `.exe` は後ろの列として扱う
104	    while pos < bytes.len() && bytes[pos] == b'.' {
105	        let n = digits(pos + 1);
106	        if n == 0 {
107	            break;
108	        }
109	        pos += 1 + n;
110	        groups += 1;
111	    }
112	    if groups == 0 {
113	        return false;
114	    }
115	    match bytes.get(pos) {
116	        None => true,
117	        Some(b'-' | b'+' | b'_' | b'.') => bytes[pos + 1..]
118	            .iter()
119	            .all(|b| b.is_ascii_alphanumeric() || *b == b'.'),
120	        Some(_) => false,
121	    }
122	}
123	
124	/// Linux のカーネルスレッドか。`/proc/<pid>/exe` が読めず、自身が kthreadd（PID 2）か
125	/// その子であるものを対象外にする。Windows では常に false
126	pub fn is_kernel_thread(os: Os, info: &ProcessInfo) -> bool {
127	    os == Os::Linux && info.path.is_none() && (info.pid == 2 || info.ppid == Some(2))
128	}
129	
130	/// プロセスの識別キーを求める。対象外（カーネルスレッド）は None
131	pub fn identify(os: Os, info: &ProcessInfo) -> Option<Identity> {
132	    if is_kernel_thread(os, info) {
133	        return None;
134	    }
135	    Some(match &info.path {
136	        Some(path) => normalize_path(os, path),
137	        None => Identity {
