144	/// フラグ判定に使う、解決済みの場所。環境変数はここへ渡す前に呼び出し側が読む
145	#[derive(Debug, Clone, PartialEq, Eq)]
146	pub struct Roots {
147	    os: Os,
148	    /// 正規化済み。末尾の区切りは無い
149	    user_writable: Vec<String>,
150	    /// 正規化済み（Windows の `%SystemRoot%`）
151	    system_root: String,
152	}
