154	impl Roots {
155	    /// 渡す値は正規化前でよい。空や根（`/`）は、全部が書き込み可能になってしまうので捨てる
156	    pub fn new(os: Os, user_writable: &[&str], system_root: Option<&str>) -> Roots {
157	        let trim = |p: &str| {
158	            let (p, _) = normalize_basic(os, p);
159	            p.trim_end_matches(os.separator()).to_string()
160	        };
161	        Roots {
162	            os,
163	            user_writable: user_writable
164	                .iter()
165	                .map(|p| trim(p))
166	                .filter(|p| !p.is_empty())
167	                .collect(),
168	            system_root: trim(system_root.unwrap_or(r"C:\Windows")),
169	        }
170	    }
171	
172	    /// 実行中の環境から組み立てる。環境変数を読むのはここだけ
173	    pub fn from_env() -> Roots {
174	        let os = Os::current();
175	        let var = |name: &str| std::env::var(name).unwrap_or_default();
176	        match os {
177	            Os::Windows => {
178	                let (profile, temp, tmp, root) = (
179	                    var("USERPROFILE"),
180	                    var("TEMP"),
181	                    var("TMP"),
182	                    var("SystemRoot"),
183	                );
184	                let root = (!root.is_empty()).then_some(root.as_str());
185	                Roots::new(os, &[&profile, &temp, &tmp, r"C:\Users\Public"], root)
186	            }
187	            Os::Linux => {
188	                let home = var("HOME");
189	                Roots::new(os, &[&home, "/tmp", "/var/tmp", "/dev/shm"], None)
190	            }
191	        }
192	    }
193	}
