195	/// `path` が `dir` と同じか、その配下にあるか。どちらも正規化済み
196	fn is_under(sep: char, path: &str, dir: &str) -> bool {
197	    path.strip_prefix(dir)
198	        .is_some_and(|rest| rest.is_empty() || rest.starts_with(sep))
199	}
