201	/// user_writable: 利用者が書き込める場所（ユーザーフォルダや一時領域）の配下にある実行ファイル
202	pub fn is_user_writable(roots: &Roots, path: &str) -> bool {
203	    let (path, _) = normalize_basic(roots.os, path);
204	    roots
205	        .user_writable
206	        .iter()
207	        .any(|dir| is_under(roots.os.separator(), &path, dir))
208	}
