226	/// masquerade: Windows のシステムプロセスの名前なのに、置き場所が違う。
227	/// パスが取れないもの（`path` が None）は判定しない。Linux では常に false
228	pub fn is_masquerade(roots: &Roots, name: &str, path: Option<&str>) -> bool {
229	    if roots.os != Os::Windows {
230	        return false;
231	    }
232	    let Some(path) = path else {
233	        return false;
234	    };
235	    let name = name.to_ascii_lowercase();
236	    let (path, _) = normalize_basic(roots.os, path);
237	    // 名前の表に無ければ対象外。explorer.exe だけは %SystemRoot% 直下が正しい置き場所
238	    let allowed: Vec<String> = if name == "explorer.exe" {
239	        vec![roots.system_root.clone()]
240	    } else if SYSTEM_PROCESS_NAMES.contains(&name.as_str()) {
241	        vec![
242	            format!(r"{}\system32", roots.system_root),
243	            format!(r"{}\syswow64", roots.system_root),
244	        ]
245	    } else {
246	        return false;
247	    };
248	    // 親ディレクトリの完全一致で見る。`system32\evil\svchost.exe` も不正にする
249	    let parent = path.rsplit_once('\\').map_or("", |(dir, _)| dir);
250	    !allowed.iter().any(|dir| dir == parent)
251	}
