253	/// 根のプロセスとその子孫を除いたプロセス一覧を返す。
254	///
255	/// `roots` は (PID, 起動時刻)。kuda 自身と実行中の調査プロセスを渡す。
256	/// 判断はすべて「除外しすぎない」側に倒す。除外は見えなくする操作なので、
257	/// 誤って除くより、kuda 自身が未知として見えるほうがまだ安全だから。
258	/// - 根は、一覧に同じ PID がいて起動時刻が一致するときだけ生きているとみなす（PID 再利用対策）
259	/// - 親子は、親の起動時刻 ≤ 子の起動時刻のときだけたどる。
260	///   どちらかの起動時刻が None のときは確かめられないので、たどらない
261	pub fn without_descendants<'a>(
262	    processes: &'a [ProcessInfo],
263	    roots: &[(u32, i64)],
264	) -> Vec<&'a ProcessInfo> {
265	    let by_pid: HashMap<u32, &ProcessInfo> = processes.iter().rev().map(|p| (p.pid, p)).collect();
266	    let mut children: HashMap<u32, Vec<&ProcessInfo>> = HashMap::new();
267	    for p in processes {
268	        if let Some(ppid) = p.ppid {
269	            children.entry(ppid).or_default().push(p);
270	        }
271	    }
272	
273	    let mut excluded: HashSet<u32> = HashSet::new();
274	    let mut queue: Vec<&ProcessInfo> = roots
275	        .iter()
276	        .filter_map(|&(pid, started)| {
277	            by_pid
278	                .get(&pid)
279	                .copied()
280	                .filter(|p| p.started == Some(started))
281	        })
282	        .collect();
283	    while let Some(parent) = queue.pop() {
284	        if !excluded.insert(parent.pid) {
285	            continue;
286	        }
287	        for &child in children.get(&parent.pid).into_iter().flatten() {
288	            match (parent.started, child.started) {
289	                (Some(ps), Some(cs)) if ps <= cs => queue.push(child),
290	                _ => {}
291	            }
292	        }
293	    }
294	    processes
295	        .iter()
296	        .filter(|p| !excluded.contains(&p.pid))
297	        .collect()
298	}
