300	/// `*`（区切りも跨ぐ）だけを扱う glob。大文字小文字は区別しない
301	/// （パターンもパスも小文字にそろえる。Linux のパスも同じ扱いにして規則を 1 つにする）
302	pub fn glob_match(pattern: &str, text: &str) -> bool {
303	    let pattern: Vec<char> = pattern.to_lowercase().chars().collect();
304	    let text: Vec<char> = text.to_lowercase().chars().collect();
305	    let (mut p, mut t) = (0, 0);
306	    // 直近の `*` の位置と、そのとき `*` に食わせていた text の終端
307	    let mut star: Option<(usize, usize)> = None;
308	    while t < text.len() {
309	        if p < pattern.len() && pattern[p] == '*' {
310	            star = Some((p, t));
311	            p += 1;
312	        } else if p < pattern.len() && pattern[p] == text[t] {
313	            p += 1;
314	            t += 1;
315	        } else if let Some((sp, st)) = star {
316	            p = sp + 1;
317	            t = st + 1;
318	            star = Some((sp, st + 1));
319	        } else {
320	            return false;
321	        }
322	    }
323	    pattern[p..].iter().all(|&c| c == '*')
324	}
