326	/// 自プロセスを `without_descendants` の根にするための (PID, 起動時刻)。
327	/// 起動時刻は列挙結果から自 PID を引いて得る。見つからなければ除外できない
328	pub fn own_root(processes: &[ProcessInfo]) -> Option<(u32, i64)> {
329	    let pid = std::process::id();
330	    processes
331	        .iter()
332	        .find(|p| p.pid == pid)
333	        .and_then(|p| p.started.map(|started| (pid, started)))
334	}
