347	/// （異常と判定されたとき、学習しない形でやり直すため）
348	#[derive(Debug, Clone, PartialEq)]
349	pub struct Classification {
350	    /// unknown / unknown_user_writable / masquerade / missing / process_count
351	    pub metrics: Variables,
352	    /// 今 動いている pending。事件の証拠にする
353	    pub pending: Vec<PendingProcess>,
354	    /// 新しく known として登録する識別キーの数
355	    pub learned: usize,
