375	/// 識別キーごとにまとめた、今 動いているプロセス
376	struct Observed<'a> {
377	    identity: Identity,
378	    process: &'a ProcessInfo,
379	    user_writable: bool,
380	    masquerade: bool,
381	}
382	
383	/// 動いているプロセスを既知の集合と照らして分類する。ストアは読むだけ。
384	///
385	/// `learn` が true で学習期間中なら、新しく見た識別キーを known にする（masquerade を除く）。
386	/// それ以外の新しい識別キーは pending にする。`excluded` は kuda 自身と調査プロセスの根
387	pub fn classify(
388	    store: &Store,
389	    watch: &Watch,
390	    processes: &[ProcessInfo],
391	    excluded: &[(u32, i64)],
392	    roots: &Roots,
393	    now: i64,
394	    learn: bool,
395	) -> Result<Classification> {
396	    let os = roots.os;
397	    let probe = &watch.probe;
398	    let mut observed: BTreeMap<String, Observed> = BTreeMap::new();
399	    for process in without_descendants(processes, excluded) {
400	        let Some(identity) = identify(os, process) else {
401	            continue;
402	        };
403	        if probe.ignore.iter().any(|g| glob_match(g, &identity.key)) {
404	            continue;
405	        }
406	        let path = process.path.as_deref();
407	        let masquerade = is_masquerade(roots, &process.name, path);
408	        let user_writable = path.is_some_and(|p| is_user_writable(roots, p));
409	        let entry = observed
410	            .entry(identity.key.clone())
411	            .or_insert_with(|| Observed {
412	                identity,
413	                process,
414	                user_writable,
415	                masquerade,
416	            });
417	        // 代表は PID が最小のもの。列挙の順序に結果を依存させない
418	        if process.pid < entry.process.pid {
419	            entry.process = process;
420	        }
421	        entry.masquerade |= masquerade;
422	    }
423	
424	    let started = store.learning_started(&watch.name)?.unwrap_or(now);
425	    let learning = watch
426	        .baseline
427	        .learn_for
428	        .is_some_and(|d| now < started.saturating_add(d.as_secs() as i64));
429	    let statuses = store.identity_statuses(&watch.name)?;
430	
431	    let mut seen = Vec::new();
432	    let mut pending = Vec::new();
433	    let mut learned = 0;
434	    for (key, o) in &observed {
435	        let status = match statuses.get(key) {
436	            Some(status) => *status,
437	            // 偽装は、学習期間中でも正常として覚えない
438	            None if learn && learning && !o.masquerade => {
439	                learned += 1;
440	                IdentityStatus::Known
441	            }
442	            None => IdentityStatus::Pending,
443	        };
444	        seen.push((key.clone(), status));
445	        if status == IdentityStatus::Pending {
446	            pending.push(PendingProcess {
447	                identity: o.identity.clone(),
448	                process: o.process.clone(),
449	                user_writable: o.user_writable,
450	                masquerade: o.masquerade,
451	            });
452	        }
453	    }
454	
455	    let count = |f: fn(&PendingProcess) -> bool| pending.iter().filter(|p| f(p)).count() as f64;
456	    let missing = probe
457	        .expected
458	        .iter()
459	        .filter(|g| !observed.keys().any(|key| glob_match(g, key)))
460	        .count();
461	    let mut metrics = Variables::new();
462	    metrics.insert("unknown".to_string(), pending.len() as f64);
463	    metrics.insert(
464	        "unknown_user_writable".to_string(),
465	        count(|p| p.user_writable),
466	    );
467	    metrics.insert("masquerade".to_string(), count(|p| p.masquerade));
468	    metrics.insert("missing".to_string(), missing as f64);
469	    metrics.insert("process_count".to_string(), observed.len() as f64);
470	    Ok(Classification {
471	        metrics,
472	        pending,
473	        learned,
474	        seen,
475	    })
476	}
