52	/// 秒単位の時刻から一意なディレクトリを作る。同じ秒に重なったら連番を付ける
53	fn create_unique_dir(parent: &Path, created: i64) -> Result<(String, PathBuf)> {
54	    create_private_dir(parent)?;
55	    let base = Local.timestamp_opt(created, 0).single().map_or_else(
56	        || created.to_string(),
57	        |time| time.format("%Y%m%d-%H%M%S").to_string(),
58	    );
59	    for attempt in 1..100 {
60	        let id = match attempt {
61	            1 => base.clone(),
62	            n => format!("{base}-{n}"),
63	        };
64	        let dir = parent.join(&id);
65	        if !dir.exists() {
66	            create_private_dir(&dir)?;
67	            return Ok((id, dir));
68	        }
69	    }
70	    anyhow::bail!("too many incidents at {base}");
71	}
