73	pub fn create(incidents_dir: &Path, evidence: &Evidence, created: i64) -> Result<Incident> {
74	    let (id, dir) = create_unique_dir(&incidents_dir.join(evidence.watch), created)?;
75	    let incident = Incident {
76	        watch: evidence.watch.to_string(),
77	        id,
