106	pub fn load(dir: &Path) -> Result<Incident> {
107	    let path = dir.join(META_FILE);
108	    let text = std::fs::read_to_string(&path)
109	        .with_context(|| format!("failed to read {}", path.display()))?;
110	    let mut incident: Incident = serde_json::from_str(&text)?;
111	    // watch と id はレポートの保存先パスに使う。他人から受け取った事件でも外へ書かせない
112	    ensure!(
113	        is_safe_name(&incident.watch),
114	        "{} has an invalid watch: {:?}",
115	        path.display(),
116	        incident.watch
117	    );
118	    ensure!(
119	        is_incident_id(&incident.id),
120	        "{} has an invalid id: {:?}",
121	        path.display(),
122	        incident.id
123	    );
124	    incident.dir = dir.to_path_buf();
125	    Ok(incident)
