128	/// 保持期間を過ぎた事件ディレクトリを削除する
129	pub fn prune(incidents_dir: &Path, retention_days: u32, now: i64) -> Result<()> {
130	    let cutoff = now - i64::from(retention_days) * 86400;
131	    for watch_dir in std::fs::read_dir(incidents_dir)? {
132	        let watch_dir = watch_dir?.path();
133	        if !watch_dir.is_dir() {
134	            continue;
135	        }
136	        for entry in std::fs::read_dir(&watch_dir)? {
137	            let dir = entry?.path();
138	            if load(&dir).is_ok_and(|incident| incident.created < cutoff) {
139	                std::fs::remove_dir_all(&dir)
140	                    .with_context(|| format!("failed to remove {}", dir.display()))?;
141	            }
142	        }
143	    }
144	    Ok(())
145	}
