158	    let _ = writeln!(text, "# 事件サマリ: {}\n", evidence.watch);
159	    let _ = writeln!(text, "- 検出時刻: {}", format_time(created));
160	    let _ = writeln!(text, "- 発生開始: {}", format_time(evidence.since));
161	    let _ = writeln!(text, "- 理由: {}", evidence.reason);
162	    let _ = writeln!(text, "- OS: {}", std::env::consts::OS);
163	
164	    text.push_str("\n## 現在の指標\n\n| 指標 | 値 |\n| --- | --- |\n");
165	    for (name, value) in evidence.run.metrics() {
166	        let _ = writeln!(text, "| {name} | {value:.3} |");
167	    }
168	
169	    text.push_str(
170	        "\n## ターゲット別の結果\n\n| ターゲット | 結果 | RTT | エラー |\n| --- | --- | --- | --- |\n",
171	    );
172	    for result in &evidence.run.results {
173	        let _ = writeln!(
174	            text,
175	            "| {} | {} | {} | {} |",
176	            cell(&result.target),
177	            if result.ok { "成功" } else { "失敗" },
178	            format_ms(result.rtt_ms),
179	            cell(result.error.as_deref().unwrap_or("-")),
180	        );
181	    }
182	
183	    text.push_str("\n## ベースライン\n\n");
184	    if evidence.stats.is_empty() {
185	        text.push_str("データ不足のため、まだありません。\n");
186	    } else {
187	        text.push_str(
188	            "| 系列 | 集計 | サンプル数 | p50 | p95 |\n| --- | --- | --- | --- | --- |\n",
189	        );
190	        for stat in evidence.stats {
191	            let source = match stat.source {
192	                Source::Bucket => "同時間帯",
193	                Source::Overall => "全体",
194	            };
195	            let _ = writeln!(
196	                text,
197	                "| {} | {source} | {} | {:.3} | {:.3} |",
198	                stat.series, stat.samples, stat.p50, stat.p95
199	            );
200	        }
201	    }
202	
203	    text.push_str("\n## 最後の正常時スナップショット\n\n");
204	    text.push_str("collector ごとに、最後に取得に成功した時点のデータと比べます。\n\n");
205	    let mut names = collector_names(evidence.current);
206	    if let Some(last_good) = evidence.last_good {
207	        names.extend(collector_names(last_good));
208	    }
209	    names.sort();
210	    names.dedup();
211	    if names.is_empty() {
212	        text.push_str("ありません。\n");
213	    }
214	    for name in names {
215	        let taken_at = evidence
216	            .last_good
217	            .and_then(|last_good| last_good["collectors"][&name]["taken_at"].as_i64());
218	        let time = taken_at.map_or_else(|| "成功した取得がありません".to_string(), format_time);
219	        let _ = writeln!(text, "- `{name}`: {time}");
220	    }
221	    text
222	}
