224	/// 比較基準の取得時刻。collector ごとに異なりうるので、異なれば範囲で示す
225	fn baseline_time(last_good: &Value) -> String {
226	    let times: Vec<i64> = last_good["collectors"]
227	        .as_object()
228	        .into_iter()
229	        .flatten()
230	        .filter_map(|(_, entry)| entry["taken_at"].as_i64())
231	        .collect();
232	    match (times.iter().min(), times.iter().max()) {
233	        (Some(first), Some(last)) if first == last => format_time(*first),
234	        (Some(first), Some(last)) => format!(
235	            "{} 〜 {}（collector ごとに最後に成功した時点）",
236	            format_time(*first),
237	            format_time(*last)
238	        ),
239	        _ => "?".to_string(),
240	    }
241	}
242	
243	fn render_metrics(evidence: &Evidence) -> String {
244	    let baseline = |metric: &str| {
245	        let series = match metric {
246	            "rtt_p50" => "rtt",
247	            other => other,
248	        };
249	        let stat = evidence.stats.iter().find(|stat| stat.series == series);
250	        stat.map_or_else(
251	            || ",".to_string(),
252	            |stat| format!("{:.3},{:.3}", stat.p50, stat.p95),
253	        )
254	    };
255	    let mut text = "time,metric,value,baseline_p50,baseline_p95\n".to_string();
256	    for row in evidence.history {
257	        let _ = writeln!(
258	            text,
259	            "{},{},{:.3},{}",
260	            format_time(row.ts),
261	            row.name,
262	            row.value,
263	            baseline(&row.name)
264	        );
265	    }
266	    text
267	}
268	
269	fn scalar(value: &Value) -> String {
270	    match value {
271	        Value::String(text) => text.clone(),
272	        Value::Null => "*".to_string(),
273	        other => other.to_string(),
274	    }
275	}
276	
277	fn identity(item: &Value) -> Option<String> {
278	    let parts: Vec<String> = IDENTITY_KEYS
279	        .iter()
280	        .filter_map(|key| item.get(key).filter(|v| !v.is_null()).map(scalar))
281	        .collect();
282	    (!parts.is_empty()).then(|| parts.join(" "))
283	}
284	
285	/// JSON をパスと値の組へ平坦化する
286	fn flatten(path: &str, value: &Value, out: &mut BTreeMap<String, String>) {
287	    match value {
288	        Value::Object(map) => {
289	            for (key, value) in map {
290	                if !VOLATILE_KEYS.contains(&key.as_str()) {
291	                    flatten(&format!("{path}.{key}"), value, out);
292	                }
293	            }
294	        }
295	        Value::Array(items) if items.iter().all(Value::is_object) && !items.is_empty() => {
296	            for (index, item) in items.iter().enumerate() {
297	                let id = identity(item).unwrap_or_else(|| index.to_string());
298	                flatten(&format!("{path}[{id}]"), item, out);
299	            }
300	        }
301	        // アドレス一覧や traceroute のホップは 1 つの値として並びごと比べる
302	        Value::Array(items) => {
303	            let joined: Vec<String> = items.iter().map(scalar).collect();
304	            out.insert(path.to_string(), joined.join(" → "));
305	        }
306	        other => {
307	            out.insert(path.to_string(), scalar(other));
308	        }
309	    }
310	}
311	
312	fn collector_data(snapshot: &Value, name: &str) -> Option<BTreeMap<String, String>> {
313	    let entry = snapshot["collectors"].get(name)?;
314	    if entry["ok"] != Value::Bool(true) {
315	        return None;
316	    }
317	    let mut flat = BTreeMap::new();
318	    flatten(name, &entry["data"], &mut flat);
319	    Some(flat)
320	}
321	
322	fn collector_names(snapshot: &Value) -> Vec<String> {
323	    snapshot["collectors"]
324	        .as_object()
325	        .map(|map| map.keys().cloned().collect())
326	        .unwrap_or_default()
327	}
328	
329	fn render_diff(last_good: Option<&Value>, current: &Value) -> String {
330	    let mut text = "# 正常時との差分\n\n".to_string();
331	    let Some(last_good) = last_good else {
332	        text.push_str("比較できる正常時のスナップショットがありません。\n");
333	        return text;
334	    };
335	    let _ = writeln!(
336	        text,
337	        "基準: {} / 現在: {}\n",
338	        baseline_time(last_good),
339	        current["taken_at"]
340	            .as_i64()
341	            .map_or_else(|| "?".to_string(), format_time),
342	    );
343	
344	    let mut names = collector_names(last_good);
345	    names.extend(collector_names(current));
346	    names.sort();
347	    names.dedup();
348	
349	    let (mut changed, mut added, mut removed, mut failed) =
350	        (Vec::new(), Vec::new(), Vec::new(), Vec::new());
351	    for name in names {
352	        let (Some(old), Some(new)) = (
353	            collector_data(last_good, &name),
354	            collector_data(current, &name),
355	        ) else {
356	            // 片方で取得できていないと全項目が差分に見えるので、1 行にまとめる
357	            let error = match current["collectors"][&name]["error"].as_str() {
358	                Some(error) => error,
359	                None if current["collectors"].get(&name).is_none() => {
360	                    "現在のスナップショットに含まれていません"
361	                }
362	                None => "正常時に取得に成功したことがありません",
363	            };
364	            failed.push(format!("- `{name}`: {error}"));
365	            continue;
366	        };
367	        for (path, value) in &new {
368	            match old.get(path) {
369	                None => added.push(format!("- `{path}`: {value}")),
370	                Some(previous) if previous != value => {
371	                    changed.push(format!("- `{path}`: {previous} ⇒ {value}"));
372	                }
373	                Some(_) => {}
374	            }
375	        }
376	        for (path, value) in &old {
377	            if !new.contains_key(path) {
378	                removed.push(format!("- `{path}`: {value}"));
379	            }
380	        }
381	    }
382	
383	    if changed.is_empty() && added.is_empty() && removed.is_empty() && failed.is_empty() {
384	        text.push_str("差分はありません。\n");
385	    }
386	    for (heading, lines) in [
387	        ("変更", changed),
388	        ("追加", added),
389	        ("削除", removed),
390	        ("比較できなかった項目", failed),
391	    ] {
392	        if !lines.is_empty() {
393	            let _ = writeln!(text, "## {heading}\n\n{}\n", lines.join("\n"));
394	        }
395	    }
396	    text
397	}
