1	//! LLM による調査。バックエンドの選択、フォールバック、レポートの保存。
2	//!
3	//! 使い魔は管の外へ無制限に出さない: 1 回の調査で試すのは主バックエンドと
4	//! fallback を 1 度ずつだけで、それぞれ `max_duration` で打ち切る。
5	
6	mod claude_code;
7	mod codex;
8	mod local;
