18	pub struct Request<'a> {
19	    pub prompt: &'a str,
20	    pub incident_dir: &'a Path,
21	    /// バックエンドが一時ファイルを置くための、kuda が管理するディレクトリ。
22	    /// 事件ディレクトリは外から渡されうるので、そこには書かない
23	    pub work_dir: &'a Path,
24	    pub allowed_commands: &'a [String],
25	    pub timeout: Duration,
26	}
