28	pub trait Backend {
29	    /// 使える状態か確かめる。理由を添えて失敗を返す
30	    fn available(&self) -> Result<String, String>;
31	    /// 調査を実行し、レポート本文を返す
32	    fn run(&self, request: &Request) -> Result<String>;
33	}
34	
35	pub fn backend(config: &Config, kind: BackendKind) -> Result<Box<dyn Backend>> {
36	    let missing = || format!("backend {} is not configured", kind.name());
37	    Ok(match kind {
38	        BackendKind::ClaudeCode => {
39	            let settings = config.backends.claude_code.clone();
40	            Box::new(claude_code::ClaudeCode(settings.with_context(missing)?))
41	        }
42	        BackendKind::Codex => {
43	            let settings = config.backends.codex.clone();
44	            Box::new(codex::Codex(settings.with_context(missing)?))
45	        }
46	        BackendKind::Local => {
47	            let settings = config.backends.local.clone();
48	            Box::new(local::Local(settings.with_context(missing)?))
49	        }
50	    })
51	}
