53	pub fn expand_prompt(template: &str, incident: &Incident) -> String {
54	    template
55	        .replace("{{incident_dir}}", &incident.dir.display().to_string())
56	        .replace("{{watch}}", &incident.watch)
57	        .replace("{{os}}", std::env::consts::OS)
58	        .replace("{{since}}", &format_time(incident.since))
59	}
60	
61	struct Attempt {
62	    kind: BackendKind,
63	    elapsed: Duration,
64	    error: Option<String>,
65	}
66	
67	fn attempt_order(diagnose: &Diagnose, override_kind: Option<BackendKind>) -> Vec<BackendKind> {
68	    match override_kind {
69	        Some(kind) => vec![kind],
70	        None => std::iter::once(diagnose.backend)
71	            .chain(diagnose.fallback)
72	            .collect(),
73	    }
74	}
75	
76	fn run_backend(config: &Config, kind: BackendKind, request: &Request) -> Result<String> {
77	    let backend = backend(config, kind)?;
78	    if let Err(reason) = backend.available() {
79	        bail!("not available: {reason}");
80	    }
81	    backend.run(request)
82	}
83	
84	fn render_report(incident: &Incident, attempts: &[Attempt], body: &str) -> String {
85	    let mut text = format!("# 調査レポート: {}\n\n", incident.watch);
86	    let _ = writeln!(text, "- 事件: {}", incident.dir.display());
87	    let _ = writeln!(text, "- 発生開始: {}", format_time(incident.since));
88	    for attempt in attempts {
89	        let elapsed = attempt.elapsed.as_secs_f64();
90	        let outcome = match &attempt.error {
91	            None => "成功".to_string(),
92	            Some(error) => format!("失敗: {error}"),
93	        };
94	        let name = attempt.kind.name();
95	        let _ = writeln!(text, "- バックエンド {name}: {outcome}（{elapsed:.1} 秒）");
96	    }
97	    let _ = writeln!(text, "\n{body}");
98	    text
99	}
