101	/// レポートの保存先。watch と id が 1 つのパス要素でなければ reports の外を指しうるので拒む
102	pub fn report_path(paths: &Paths, incident: &Incident) -> Result<PathBuf> {
103	    ensure!(
104	        is_safe_name(&incident.watch) && is_safe_name(&incident.id),
105	        "unsafe incident name: watch {:?}, id {:?}",
106	        incident.watch,
107	        incident.id
108	    );
109	    Ok(paths
110	        .reports_dir
111	        .join(&incident.watch)
112	        .join(format!("{}.md", incident.id)))
113	}
