115	/// 調査を実行してレポートを保存し、そのパスを返す。全バックエンドが失敗しても
116	/// 失敗の記録をレポートとして残したうえでエラーを返す
117	pub fn investigate(
118	    config: &Config,
119	    paths: &Paths,
120	    diagnose: &Diagnose,
121	    incident: &Incident,
122	    override_kind: Option<BackendKind>,
123	) -> Result<PathBuf> {
124	    let path = report_path(paths, incident)?;
125	    let prompt_path = paths.config_dir.join(&diagnose.prompt_file);
126	    let template = std::fs::read_to_string(&prompt_path)
127	        .with_context(|| format!("failed to read {}", prompt_path.display()))?;
128	    let prompt = expand_prompt(&template, incident);
129	    let request = Request {
130	        prompt: &prompt,
131	        incident_dir: &incident.dir,
132	        work_dir: &paths.data_dir,
133	        allowed_commands: diagnose.allowed_commands.current(),
134	        timeout: diagnose.max_duration,
135	    };
136	
137	    let mut attempts = Vec::new();
138	    let mut body = None;
139	    for kind in attempt_order(diagnose, override_kind) {
140	        log::info!("investigating {} with {}", incident.id, kind.name());
141	        let started = Instant::now();
142	        let result = run_backend(config, kind, &request);
143	        let elapsed = started.elapsed();
144	        match result {
145	            Ok(text) => {
146	                attempts.push(Attempt {
147	                    kind,
148	                    elapsed,
149	                    error: None,
150	                });
151	                body = Some(text);
152	                break;
153	            }
154	            Err(error) => {
155	                log::warn!("backend {} failed: {error:#}", kind.name());
156	                attempts.push(Attempt {
157	                    kind,
158	                    elapsed,
159	                    error: Some(format!("{error:#}")),
160	                });
161	            }
162	        }
163	    }
164	
165	    create_private_dir(&paths.reports_dir.join(&incident.watch))?;
166	    let succeeded = body.is_some();
167	    let body = body.unwrap_or_else(|| "すべてのバックエンドが失敗しました。".to_string());
168	    std::fs::write(&path, render_report(incident, &attempts, &body))
169	        .with_context(|| format!("failed to write {}", path.display()))?;
170	    if !succeeded {
171	        bail!("all backends failed; see {}", path.display());
172	    }
173	    Ok(path)
174	}
