1	//! スナップショットを構成する、システム状態の収集。
2	
3	mod adapters;
4	mod dns_config;
5	mod routes;
6	mod traceroute;
7	
8	use crate::config::CollectorSpec;
9	use anyhow::Result;
10	use serde_json::{Map, Value, json};
11	
12	pub use routes::default_gateway;
13	
14	fn collect(spec: &CollectorSpec) -> Result<Value> {
15	    match spec {
16	        CollectorSpec::Adapters => adapters::collect(),
17	        CollectorSpec::Routes => routes::collect(),
18	        CollectorSpec::DnsConfig => dns_config::collect(),
19	        CollectorSpec::Traceroute(target) => traceroute::collect(target),
20	    }
21	}
22	
23	/// 全 collector を並列に実行する。個別の失敗はスナップショット内に記録して続行する
24	pub fn take_snapshot(specs: &[CollectorSpec], taken_at: i64) -> Value {
25	    take_snapshot_with(specs, taken_at, collect)
26	}
27	
28	/// `collect` で各 collector を実行する。panic も失敗として記録する。
29	/// 結果から落とすと、全 collector が成功した取得に見えてしまう
30	fn take_snapshot_with(
31	    specs: &[CollectorSpec],
32	    taken_at: i64,
33	    collect: fn(&CollectorSpec) -> Result<Value>,
34	) -> Value {
35	    let results: Vec<(String, Value)> = std::thread::scope(|scope| {
36	        let handles: Vec<_> = specs
37	            .iter()
38	            .map(|spec| (spec.name(), scope.spawn(move || collect(spec))))
39	            .collect();
40	        handles
41	            .into_iter()
42	            .map(|(name, handle)| {
43	                let result = handle
44	                    .join()
45	                    .unwrap_or_else(|_| Err(anyhow::anyhow!("collector panicked")));
46	                match result {
47	                    Ok(data) => (name, json!({ "ok": true, "data": data })),
48	                    Err(error) => {
49	                        log::warn!("collector {name} failed: {error:#}");
50	                        (name, json!({ "ok": false, "error": format!("{error:#}") }))
51	                    }
52	                }
53	            })
54	            .collect()
55	    });
56	    let collectors: Map<String, Value> = results.into_iter().collect();
57	    json!({ "taken_at": taken_at, "collectors": collectors })
58	}
