1	//! 実行中の調査（`kuda diagnose`）の記録。
2	//!
3	//! 調査プロセスは detach されるので、check からは親子関係でたどれない。
4	//! そこで調査の間だけ、状態ディレクトリに (PID, 起動時刻) を置き、
5	//! プロセスの監視が kuda 自身の仲間として除外できるようにする。
6	
7	use crate::known_set;
8	use crate::paths::Paths;
9	use crate::probe::ProcessInfo;
10	use anyhow::{Context, Result};
11	use std::path::PathBuf;
12	
13	const PREFIX: &str = "investigating-";
14	
15	/// 記録を、Drop で消す。異常終了で残っても、`running` が生きていないものとして無視する
16	pub struct Registration(PathBuf);
17	
18	impl Drop for Registration {
19	    fn drop(&mut self) {
20	        // 消せなくても出来ることがない。残っても害はない（`running` が無視し、次の調査が上書きする）
21	        let _ = std::fs::remove_file(&self.0);
22	    }
23	}
24	
25	/// 自プロセスを調査プロセスとして記録する。
26	/// `processes` は今の列挙結果で、自分の起動時刻を引くのに使う。引けなければ記録しない
27	pub fn register(
28	    paths: &Paths,
29	    watch: &str,
30	    processes: &[ProcessInfo],
31	) -> Result<Option<Registration>> {
32	    let Some((pid, started)) = known_set::own_root(processes) else {
33	        return Ok(None);
34	    };
35	    let path = paths.data_dir.join(format!("{PREFIX}{watch}"));
36	    std::fs::write(&path, format!("{pid} {started}"))
37	        .with_context(|| format!("failed to write {}", path.display()))?;
38	    Ok(Some(Registration(path)))
39	}
40	
41	/// 生きている調査プロセスの (PID, 起動時刻)。
42	/// 一致するプロセスがいない記録は無視するだけで消さない。check の列挙の直後に始まった調査の
43	/// 記録も、列挙結果には一致しないので、消すと生きている調査を巻き込む
44	pub fn running(paths: &Paths, processes: &[ProcessInfo]) -> Vec<(u32, i64)> {
45	    let Ok(entries) = std::fs::read_dir(&paths.data_dir) else {
46	        return Vec::new();
47	    };
48	    let mut roots = Vec::new();
49	    for entry in entries.flatten() {
50	        if !entry.file_name().to_string_lossy().starts_with(PREFIX) {
51	            continue;
52	        }
53	        let Some(root) = std::fs::read_to_string(entry.path())
54	            .ok()
55	            .and_then(|text| parse(&text))
56	        else {
57	            // 書き込み途中かもしれないので、読めないものは触らない
58	            continue;
59	        };
60	        if processes
61	            .iter()
62	            .any(|p| p.pid == root.0 && p.started == Some(root.1))
63	        {
64	            roots.push(root);
65	        }
66	    }
67	    roots
68	}
69	
70	fn parse(text: &str) -> Option<(u32, i64)> {
71	    let (pid, started) = text.trim().split_once(' ')?;
72	    Some((pid.parse().ok()?, started.parse().ok()?))
73	}
74	
