1	//! 調査プロセスを親から切り離して起動する。
2	//!
3	//! スケジューラはタスクの終了時に残ったプロセスも止めるので、そのまま子として
4	//! 起動すると調査が途中で消える。
5	
6	use anyhow::{Context, Result};
7	use std::path::Path;
8	use std::process::{Command, Stdio};
9	
10	/// 切り離した調査は誰も画面で見ていないので、通知を求める（設定で切っていれば出ない）
11	fn diagnose_command(program: &Path, watch: &str, incident_dir: &Path) -> Vec<String> {
12	    vec![
13	        program.display().to_string(),
14	        "diagnose".to_string(),
15	        "--watch".to_string(),
16	        watch.to_string(),
17	        "--incident".to_string(),
18	        incident_dir.display().to_string(),
19	        "--notify".to_string(),
20	    ]
21	}
22	
23	pub fn spawn_diagnose(watch: &str, incident_dir: &Path) -> Result<()> {
24	    let program = std::env::current_exe().context("failed to locate the kuda binary")?;
25	    spawn(watch, &diagnose_command(&program, watch, incident_dir))
26	}
27	
28	fn base_command(argv: &[String]) -> Command {
29	    let mut command = Command::new(&argv[0]);
30	    command
31	        .args(&argv[1..])
32	        .stdin(Stdio::null())
33	        .stdout(Stdio::null())
34	        .stderr(Stdio::null());
35	    command
36	}
37	
38	#[cfg(windows)]
39	fn spawn(_watch: &str, argv: &[String]) -> Result<()> {
40	    use std::os::windows::process::CommandExt;
41	
42	    const CREATE_BREAKAWAY_FROM_JOB: u32 = 0x0100_0000;
43	    const DETACHED_PROCESS: u32 = 0x0000_0008;
44	    const CREATE_NO_WINDOW: u32 = 0x0800_0000;
45	    const ERROR_ACCESS_DENIED: i32 = 5;
46	
47	    let flags = DETACHED_PROCESS | CREATE_NO_WINDOW;
48	    let result = base_command(argv)
49	        .creation_flags(flags | CREATE_BREAKAWAY_FROM_JOB)
50	        .spawn();
51	    match result {
52	        Ok(_) => Ok(()),
53	        // ジョブが離脱を許可していないと失敗する。切り離せなくても調査は試みる
54	        Err(error) if error.raw_os_error() == Some(ERROR_ACCESS_DENIED) => {
55	            log::warn!("job does not allow breakaway; diagnose may end with the task");
56	            base_command(argv)
57	                .creation_flags(flags)
58	                .spawn()
59	                .map(drop)
60	                .context("failed to start diagnose")
61	        }
62	        Err(error) => Err(error).context("failed to start diagnose"),
63	    }
64	}
65	
66	#[cfg(unix)]
67	fn spawn(watch: &str, argv: &[String]) -> Result<()> {
68	    use crate::process;
69	    use std::os::unix::process::CommandExt;
70	    use std::time::Duration;
71	
72	    // ユーザーの systemd が動いていれば別ユニットにする。cgroup ごと止められずに済み、
73	    // 同名ユニットが動いていれば起動に失敗するので多重起動防止にもなる
74	    if std::env::var_os("XDG_RUNTIME_DIR").is_some()
75	        && let Some(systemd_run) = process::find_program("systemd-run")
76	    {
77	        let mut command = process::command(systemd_run);
78	        command.args(systemd_run_args(watch, |key| std::env::var(key).ok()));
79	        command.args(argv);
80	        match process::run(command, None, Duration::from_secs(10)) {
81	            Ok(output) if output.success() => return Ok(()),
82	            Ok(output) if output.stderr.contains("already") => {
83	                log::info!("diagnose for {watch} is already running");
84	                return Ok(());
85	            }
86	            Ok(output) => log::warn!("systemd-run failed: {}", output.stderr.trim()),
87	            Err(error) => log::warn!("systemd-run failed: {error:#}"),
88	        }
89	    }
90	
91	    // cron など systemd の外から起動された場合は、セッションから切り離すだけにする
92	    base_command(argv)
93	        .process_group(0)
94	        .spawn()
95	        .map(drop)
96	        .context("failed to start diagnose")
97	}
98	
99	/// 別ユニットはサービスマネージャの環境で動くので、解決に使う変数を引き継ぐ
100	#[cfg(any(unix, test))]
101	fn systemd_run_args(watch: &str, env: impl Fn(&str) -> Option<String>) -> Vec<String> {
102	    let mut args = vec![
103	        "--user".to_string(),
104	        "--collect".to_string(),
105	        "--quiet".to_string(),
106	        format!("--unit=kuda-diagnose-{watch}"),
107	    ];
108	    for key in [
109	        "PATH",
110	        "KUDA_HOME",
111	        "XDG_CONFIG_HOME",
112	        "XDG_STATE_HOME",
113	        "XDG_DATA_HOME",
114	    ] {
115	        if let Some(value) = env(key) {
116	            args.push(format!("--setenv={key}={value}"));
117	        }
118	    }
119	    args
120	}
121	
