1	//! OS 別のディレクトリ解決。Linux は XDG Base Directory Specification に従う。
2	
3	use anyhow::{Context, Result, anyhow};
4	use std::path::{Path, PathBuf};
5	
6	#[derive(Debug, Clone, PartialEq)]
7	pub struct Paths {
8	    pub config_dir: PathBuf,
9	    pub data_dir: PathBuf,
10	    pub incidents_dir: PathBuf,
11	    pub logs_dir: PathBuf,
12	    pub reports_dir: PathBuf,
13	    pub lock_dir: PathBuf,
14	    /// XDG_RUNTIME_DIR が無くロックを state 側へ退避したとき true
15	    pub lock_fallback: bool,
16	}
17	
18	impl Paths {
19	    pub fn config_file(&self) -> PathBuf {
20	        self.config_dir.join("config.toml")
21	    }
22	
23	    pub fn db_file(&self) -> PathBuf {
24	        self.data_dir.join("kuda.db")
25	    }
26	
27	    pub fn lock_file(&self) -> PathBuf {
28	        self.lock_dir.join("kuda.lock")
29	    }
30	
31	    pub fn from_env() -> Result<Self> {
32	        Self::resolve(cfg!(windows), |key| std::env::var(key).ok())
33	    }
34	
35	    fn resolve(windows: bool, env: impl Fn(&str) -> Option<String>) -> Result<Self> {
36	        let var = |key: &str| env(key).filter(|v| !v.is_empty());
37	
38	        if let Some(home) = var("KUDA_HOME") {
39	            let root =
40	                std::path::absolute(&home).with_context(|| format!("invalid KUDA_HOME: {home}"))?;
41	            return Ok(Self::single_root(root));
42	        }
43	        if windows {
44	            // 設定はユーザーに付いて回るもの、それ以外はこの PC に固有のもの
45	            let roaming = var("APPDATA").ok_or_else(|| anyhow!("APPDATA is not set"))?;
46	            let local = var("LOCALAPPDATA").ok_or_else(|| anyhow!("LOCALAPPDATA is not set"))?;
47	            return Ok(Self {
48	                config_dir: PathBuf::from(roaming).join("kuda"),
49	                ..Self::single_root(PathBuf::from(local).join("kuda"))
50	            });
51	        }
52	
53	        let home = var("HOME").ok_or_else(|| anyhow!("HOME is not set"))?;
54	        // 仕様どおり、相対パスの値は無効として既定値へ戻す
55	        let xdg = |key: &str, default: &str| {
56	            var(key)
57	                .map(PathBuf::from)
58	                .filter(|p| p.is_absolute())
59	                .unwrap_or_else(|| Path::new(&home).join(default))
60	                .join("kuda")
61	        };
62	        let state = xdg("XDG_STATE_HOME", ".local/state");
63	        let runtime = var("XDG_RUNTIME_DIR")
64	            .map(PathBuf::from)
65	            .filter(|p| p.is_absolute());
66	
67	        Ok(Self {
68	            config_dir: xdg("XDG_CONFIG_HOME", ".config"),
69	            incidents_dir: state.join("incidents"),
70	            logs_dir: state.join("logs"),
71	            reports_dir: xdg("XDG_DATA_HOME", ".local/share").join("reports"),
72	            lock_fallback: runtime.is_none(),
73	            lock_dir: runtime.map_or_else(|| state.join("run"), |dir| dir.join("kuda")),
74	            data_dir: state,
75	        })
76	    }
77	
78	    fn single_root(root: PathBuf) -> Self {
79	        Self {
80	            data_dir: root.join("data"),
81	            lock_dir: root.join("data"),
82	            incidents_dir: root.join("incidents"),
83	            logs_dir: root.join("logs"),
84	            reports_dir: root.join("reports"),
85	            config_dir: root,
86	            lock_fallback: false,
87	        }
88	    }
89	
90	    /// 書き込み先のディレクトリを用意する
91	    pub fn ensure_dirs(&self) -> Result<()> {
92	        for dir in [
93	            &self.data_dir,
94	            &self.incidents_dir,
95	            &self.logs_dir,
96	            &self.reports_dir,
97	            &self.lock_dir,
98	        ] {
99	            create_private_dir(dir)?;
100	        }
101	        Ok(())
102	    }
103	}
104	
105	/// 無ければ 0700 で作成する。既にあるディレクトリのパーミッションは変えない
106	pub fn create_private_dir(dir: &Path) -> Result<()> {
107	    let mut builder = std::fs::DirBuilder::new();
108	    builder.recursive(true);
109	    #[cfg(unix)]
110	    {
111	        use std::os::unix::fs::DirBuilderExt;
112	        builder.mode(0o700);
113	    }
114	    builder
115	        .create(dir)
116	        .with_context(|| format!("failed to create {}", dir.display()))
117	}
118	
119	/// 1 つのパス要素としてそのまま使える名前か。区切り文字や `..` を通さないよう文字種を絞る
120	pub fn is_safe_name(name: &str) -> bool {
121	    !name.is_empty()
122	        && name
123	            .chars()
124	            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
125	}
