10	
11	#[cfg(windows)]
12	const CREATE_NO_WINDOW: u32 = 0x0800_0000;
13	
14	#[derive(Debug)]
15	pub struct Output {
16	    /// タイムアウトで打ち切ったときは None
17	    pub code: Option<i32>,
18	    pub stdout: String,
19	    pub stderr: String,
20	    pub timed_out: bool,
21	}
