29	/// 子プロセス用の `Command` を作る。Windows では窓が一瞬出ないようフラグを付ける
30	pub fn command(program: impl AsRef<std::ffi::OsStr>) -> Command {
31	    #[allow(unused_mut)]
32	    let mut command = Command::new(program);
33	    #[cfg(windows)]
34	    {
