41	fn capture(mut stream: impl Read + Send + 'static) -> (Arc<Mutex<Vec<u8>>>, JoinHandle<()>) {
42	    let buffer = Arc::new(Mutex::new(Vec::new()));
43	    let shared = Arc::clone(&buffer);
44	    let reader = std::thread::spawn(move || {
45	        let mut chunk = [0; 8192];
