65	/// 子プロセスとその子孫をまとめて止めるための入れ物。
66	/// Windows はジョブオブジェクト、Unix はプロセスグループで子孫を束ねる
67	#[cfg(windows)]
68	struct Tree {
69	    /// ジョブを作れなかったときは None で、直接の子だけを止める
70	    job: Option<windows::Win32::Foundation::HANDLE>,
71	}
72	
73	#[cfg(windows)]
74	impl Tree {
75	    fn prepare(_command: &mut Command) -> Self {
76	        Tree { job: None }
77	    }
78	
79	    /// ジョブに入れた後に起動された孫もジョブに属する。
80	    /// spawn から登録までの間に子が孫を起動すると取りこぼすが、その隙間はごく短い
81	    fn attach(&mut self, child: &mut Child) {
82	        use std::os::windows::io::AsRawHandle;
83	        use windows::Win32::Foundation::{CloseHandle, HANDLE};
84	        use windows::Win32::System::JobObjects::{
85	            AssignProcessToJobObject, CreateJobObjectW, JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
86	            JOBOBJECT_EXTENDED_LIMIT_INFORMATION, JobObjectExtendedLimitInformation,
87	            SetInformationJobObject,
88	        };
89	
90	        let result = unsafe {
91	            CreateJobObjectW(None, windows::core::PCWSTR::null()).and_then(|job| {
92	                // kuda が落ちてハンドルが閉じられたときも子孫ごと止まるようにする
93	                let mut info = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
94	                info.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
95	                let attached = SetInformationJobObject(
96	                    job,
97	                    JobObjectExtendedLimitInformation,
98	                    (&raw const info).cast(),
99	                    size_of_val(&info) as u32,
100	                )
101	                .and_then(|()| AssignProcessToJobObject(job, HANDLE(child.as_raw_handle())));
102	                match attached {
103	                    Ok(()) => Ok(job),
104	                    Err(error) => {
105	                        let _ = CloseHandle(job);
106	                        Err(error)
107	                    }
108	                }
109	            })
110	        };
111	        match result {
112	            Ok(job) => self.job = Some(job),
113	            // すぐ終わった子は登録が拒否される。子自身は止める必要がないので警告はしないが、
114	            // ジョブに入る前に子が起動した子孫は止められない（spawn 直後の隙間と同じ既知の制限）
115	            Err(error) if matches!(child.try_wait(), Ok(Some(_))) => {
116	                log::debug!("child exited before joining a job object: {error}");
117	            }
118	            Err(error) => log::warn!("failed to put the child in a job object: {error}"),
119	        }
120	    }
121	
122	    fn exited(&mut self, child: &mut Child) -> std::io::Result<bool> {
123	        Ok(child.try_wait()?.is_some())
124	    }
125	
126	    /// 終了を確かめられなくなったときに、子孫を残さず手を引く
127	    fn abandon(&mut self, child: &mut Child, _error: &std::io::Error) {
128	        self.kill(child);
129	        let _ = child.wait();
130	    }
131	
132	    /// 子が終了済みでも呼んでよい。その終了コードは上書きされない
133	    fn kill(&mut self, child: &mut Child) {
134	        if let Some(job) = self.job {
135	            let _ = unsafe { windows::Win32::System::JobObjects::TerminateJobObject(job, 1) };
136	        }
137	        let _ = child.kill();
138	    }
139	}
