9	/// allowed_commands を許可ルールへ変換する。Windows では Claude Code のシェルが
10	/// Git Bash になるので、PowerShell コマンドレットは powershell 経由の形にする
11	fn allow_rule(command: &str, windows: bool) -> String {
12	    let is_cmdlet = command.contains('-') && command.starts_with(char::is_uppercase);
13	    if windows && is_cmdlet {
14	        format!("Bash(powershell -NoProfile -Command {command}:*)")
15	    } else {
16	        format!("Bash({command}:*)")
17	    }
18	}
