20	/// ツールの境界をここで固定する。
21	/// - 使えるのは Read と Bash だけで、MCP サーバーも読み込まない
22	/// - Read は作業ディレクトリ（事件ディレクトリ）の中に限る
23	/// - 設定は user / project / local のどれも読まない。事件ディレクトリは第三者から
24	///   受け取ることもあり、そこの `.claude/settings.json` のフックや allow ルールを
25	///   読むと、ここで渡すルールの外でコマンドが動きうる。CLAUDE.md も読まれなくなるが、
26	///   事件ディレクトリの中身は指示ではなく調べる材料なので、それでよい
27	/// - 許可されていない操作は確認せず拒否する
28	///
29	/// `--setting-sources ""` が何も読まない意味になることは CLI に明記されていないので、
30	/// 設定ファイルを無視する `--restricted` も付ける。これを知らない古い CLI は
31	/// 未知のオプションとして起動に失敗するので、設定を読んだまま動くことはない。
32	/// `--restricted` はほかに、ファイル系ツールを作業ディレクトリに閉じ込め、`--tools` に
33	/// 無いコード実行ツールを外すが、どちらも上の方針（`Read(./**)` と Read・Bash だけ）と一致する。
34	/// `--bare` は OAuth のログインを読まなくなるので使わない
35	fn args(max_turns: u32, allowed_commands: &[String], windows: bool) -> Vec<String> {
36	    let mut args: Vec<String> = [
37	        "-p",
38	        "--output-format",
39	        "json",
40	        "--strict-mcp-config",
41	        "--restricted",
42	        "--setting-sources",
43	        "",
44	        "--permission-mode",
45	        "dontAsk",
46	        "--max-turns",
47	    ]
48	    .map(str::to_string)
49	    .to_vec();
50	    args.push(max_turns.to_string());
51	    args.extend(["--tools".to_string(), "Read".to_string()]);
52	    if !allowed_commands.is_empty() {
53	        args.push("Bash".to_string());
54	    }
55	    args.extend(["--allowedTools".to_string(), "Read(./**)".to_string()]);
56	    args.extend(allowed_commands.iter().map(|c| allow_rule(c, windows)));
57	    args
58	}
59	
60	/// `--output-format json` の出力から本文を取り出す。
61	/// バージョンによって単一の結果オブジェクトかイベントの配列かが異なる
62	fn parse_output(stdout: &str) -> Result<String> {
63	    let parsed: Value = serde_json::from_str(stdout.trim()).context("output is not JSON")?;
64	    let result = match &parsed {
65	        Value::Array(events) => events.iter().rev().find(|e| e["type"] == "result"),
66	        other => Some(other),
67	    }
68	    .context("output has no result event")?;
69	
70	    let text = result["result"].as_str().unwrap_or_default();
71	    if result["is_error"] == Value::Bool(true) {
72	        let subtype = result["subtype"].as_str().unwrap_or("unknown");
73	        bail!("claude reported an error ({subtype}): {text}");
74	    }
75	    if text.is_empty() {
76	        bail!("claude returned an empty result");
77	    }
78	    Ok(text.to_string())
79	}
80	
81	/// 失敗したときの理由を組み立てる。認証エラーなどは stdout の JSON に入っていることが
82	/// 多く、未知のオプションで起動できなかったときなどは stdout が空で stderr にだけ出る
83	fn failure_detail(stdout: &str, stderr: &str) -> String {
84	    let from_stdout = serde_json::from_str::<Value>(stdout.trim())
85	        .ok()
86	        .and_then(|_| parse_output(stdout).err())
87	        .map(|e| e.to_string());
88	    let stderr = stderr.trim();
89	    let parts: Vec<String> = from_stdout
90	        .into_iter()
91	        .chain((!stderr.is_empty()).then(|| stderr.to_string()))
92	        .collect();
93	    if parts.is_empty() {
94	        // どちらにも手がかりが無ければ、stdout を読めなかった理由だけでも返す
95	        return parse_output(stdout)
96	            .err()
97	            .map_or_else(String::new, |e| e.to_string());
98	    }
99	    parts.join("; ")
100	}
