102	impl Backend for ClaudeCode {
103	    fn available(&self) -> Result<String, String> {
104	        process::find_program(&self.0.command)
105	            .map(|path| path.display().to_string())
106	            .ok_or_else(|| format!("command not found: {}", self.0.command))
107	    }
108	
109	    fn run(&self, request: &Request) -> Result<String> {
110	        let program = process::find_program(&self.0.command)
111	            .with_context(|| format!("command not found: {}", self.0.command))?;
112	        let mut command = process::command(program);
113	        command
114	            .args(args(
115	                self.0.max_turns,
116	                request.allowed_commands,
117	                cfg!(windows),
118	            ))
119	            .current_dir(request.incident_dir);
120	        // プロンプトは複数行なので、.cmd ラッパーでも壊れないよう標準入力で渡す
121	        let output = process::run(command, Some(request.prompt), request.timeout)?;
122	        if output.timed_out {
123	            bail!("timed out after {:?}", request.timeout);
124	        }
125	        if !output.success() {
126	            let detail = failure_detail(&output.stdout, &output.stderr);
127	            bail!("exit code {:?}: {detail}", output.code);
128	        }
129	        parse_output(&output.stdout)
130	    }

