/// 実行中の OS とは限らない（テストのため）
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Os {
    Windows,
    Linux,
}

impl Os {
    pub fn current() -> Os {
        if cfg!(windows) {
            Os::Windows
        } else {
            Os::Linux
        }
    }

    pub fn separator(self) -> char {
        match self {
            Os::Windows => '\\',
            Os::Linux => '/',
        }
    }
}

