360	/// 動いているプロセスを既知の集合と照らして分類する。ストアは読むだけ。
361	///
362	/// `learn` が true で学習期間中なら、新しく見た識別キーを known にする（masquerade を除く）。
363	/// それ以外の新しい識別キーは pending にする。`excluded` は kuda 自身と調査プロセスの根
364	#[allow(clippy::too_many_arguments)]
365	pub fn classify(
366	    store: &Store,
367	    watch: &str,
368	    spec: &ProcessSpec,
369	    processes: &[ProcessInfo],
370	    excluded: &[(u32, i64)],
371	    roots: &Roots,
372	    now: i64,
373	    learn: bool,
374	) -> Result<Classification> {
375	    let os = roots.os;
376	    let mut observed: BTreeMap<String, Observed> = BTreeMap::new();
377	    for process in without_descendants(processes, excluded) {
378	        let Some(identity) = identify(os, process) else {
379	            continue;
380	        };
381	        if spec.ignore.iter().any(|g| glob_match(g, &identity.key)) {
382	            continue;
383	        }
384	        let path = process.path.as_deref();
385	        let masquerade = is_masquerade(roots, &process.name, path);
386	        let user_writable = path.is_some_and(|p| is_user_writable(roots, p));
387	        let entry = observed
388	            .entry(identity.key.clone())
389	            .or_insert_with(|| Observed {
390	                identity,
391	                process,
392	                user_writable,
393	                masquerade,
394	            });
395	        // 代表は PID が最小のもの。列挙の順序に結果を依存させない
396	        if process.pid < entry.process.pid {
397	            entry.process = process;
398	        }
399	        entry.masquerade |= masquerade;
400	    }
401	
402	    let started = store.learning_started(watch)?.unwrap_or(now);
403	    let learning = now < started.saturating_add(spec.learn_for.as_secs() as i64);
404	    let statuses = store.identity_statuses(watch)?;
405	
406	    let mut seen = Vec::new();
407	    let mut pending = Vec::new();
408	    let mut learned = 0;
409	    for (key, o) in &observed {
410	        let status = match statuses.get(key) {
411	            Some(status) => *status,
412	            // 偽装は、学習期間中でも正常として覚えない
413	            None if learn && learning && !o.masquerade => {
414	                learned += 1;
415	                IdentityStatus::Known
416	            }
417	            None => IdentityStatus::Pending,
418	        };
419	        seen.push((key.clone(), status));
420	        if status == IdentityStatus::Pending {
421	            pending.push(PendingProcess {
422	                identity: o.identity.clone(),
423	                process: o.process.clone(),
424	                user_writable: o.user_writable,
425	                masquerade: o.masquerade,
426	            });
427	        }
428	    }
429	
430	    let count = |f: fn(&PendingProcess) -> bool| pending.iter().filter(|p| f(p)).count() as f64;
431	    let missing = spec
432	        .expected
433	        .iter()
434	        .filter(|g| !observed.keys().any(|key| glob_match(g, key)))
435	        .count();
436	    let mut metrics = Variables::new();
437	    metrics.insert(metrics::UNKNOWN.to_string(), pending.len() as f64);
438	    metrics.insert(
439	        metrics::UNKNOWN_USER_WRITABLE.to_string(),
440	        count(|p| p.user_writable),
441	    );
442	    metrics.insert(metrics::MASQUERADE.to_string(), count(|p| p.masquerade));
443	    metrics.insert(metrics::MISSING.to_string(), missing as f64);
444	    metrics.insert(metrics::PROCESS_COUNT.to_string(), observed.len() as f64);
445	    Ok(Classification {
446	        metrics,
447	        pending,
448	        learned,
449	        seen,
450	    })
451	}
