20	/// ハッシュを取る実行ファイルの上限。これを超えると、check が長引くので諦める
21	const MAX_HASH_BYTES: u64 = 256 * 1024 * 1024;
22	/// ハッシュとコマンドラインを取るプロセスの数の上限。学習期間の直後などで pending が
23	/// 大量に出ても、check がスケジューラの制限（2 分）を超えないようにする
24	const MAX_DETAILED: usize = 20;
