49	/// I/O を伴わない部分。ハッシュとコマンドラインは `enrich` が埋める
50	pub fn describe(
51	    os: Os,
52	    pending: &[PendingProcess],
53	    processes: &[ProcessInfo],
54	) -> Vec<UnknownProcess> {
55	    pending
56	        .iter()
57	        .map(|p| {
58	            let process = &p.process;
59	            let parent = process
60	                .ppid
61	                .and_then(|ppid| processes.iter().find(|q| q.pid == ppid))
62	                // PID が再利用されていたら親ではない
63	                .filter(|q| match (q.started, process.started) {
64	                    (Some(parent), Some(child)) => parent <= child,
65	                    _ => true,
66	                })
67	                .and_then(|q| known_set::identify(os, q));
68	            let mut flags = Vec::new();
69	            if p.identity.deleted {
70	                flags.push("deleted");
71	            }
72	            if p.masquerade {
73	                flags.push("masquerade");
74	            }
75	            if p.user_writable {
76	                flags.push("user_writable");
77	            }
78	            UnknownProcess {
79	                identity: p.identity.key.clone(),
80	                name: process.name.clone(),
81	                path: process.path.clone(),
82	                pid: process.pid,
83	                ppid: process.ppid,
84	                parent_identity: parent.map(|identity| identity.key),
85	                user: process.user.clone(),
86	                started: process.started,
87	                flags,
88	                sha256: None,
89	                sha256_note: None,
90	                command_line: None,
91	            }
92	        })
93	        .collect()
94	}
