96	/// ハッシュとコマンドラインを取って埋める。どちらも取れなくてよい（事件の作成は止めない）
97	pub fn enrich(os: Os, unknown: &mut [UnknownProcess]) {
98	    let detailed = unknown.len().min(MAX_DETAILED);
99	    let command_lines = command_lines(os, &unknown[..detailed]);
100	    for (index, item) in unknown.iter_mut().enumerate() {
101	        if index >= detailed {
102	            let note = format!("not collected: more than {MAX_DETAILED} unknown processes");
103	            item.sha256_note = Some(note);
104	            continue;
105	        }
106	        match sha256_of(&hash_candidates(os, item.pid, item.path.as_deref())) {
107	            Ok(hash) => item.sha256 = Some(hash),
108	            Err(note) => item.sha256_note = Some(note),
109	        }
110	        item.command_line = command_lines.get(&item.pid).cloned();
111	    }
112	}
