114	/// ハッシュを取る場所の候補。Linux では `/proc/<pid>/exe` が、削除済みの実行ファイルの
115	/// 中身も読める。無ければ（または読めなければ）パスで読む
116	fn hash_candidates(os: Os, pid: u32, path: Option<&str>) -> Vec<PathBuf> {
117	    let mut candidates = Vec::new();
118	    if os == Os::Linux {
119	        candidates.push(PathBuf::from(format!("/proc/{pid}/exe")));
120	    }
121	    if let Some(path) = path {
122	        let path = path.strip_suffix(" (deleted)").unwrap_or(path);
123	        candidates.push(PathBuf::from(path));
124	    }
125	    candidates
126	}
127	
128	/// 最初に読めた候補の SHA-256 を 16 進で返す。読めなければ、理由を返す
129	fn sha256_of(candidates: &[PathBuf]) -> Result<String, String> {
130	    use sha2::{Digest, Sha256};
131	
132	    if candidates.is_empty() {
133	        return Err("no executable path".to_string());
134	    }
135	    let mut last_error = String::new();
136	    for path in candidates {
137	        let mut file = match std::fs::File::open(path) {
138	            Ok(file) => file,
139	            Err(error) => {
140	                last_error = format!("cannot open {}: {error}", path.display());
141	                continue;
142	            }
143	        };
144	        // ファイル以外（デバイスなど）を読み続けないよう、長さは開いたハンドルで確かめる
145	        match file.metadata() {
146	            Ok(meta) if meta.len() > MAX_HASH_BYTES => {
147	                return Err(format!("larger than {} MiB", MAX_HASH_BYTES / 1024 / 1024));
148	            }
149	            Ok(_) => {}
150	            Err(error) => {
151	                last_error = format!("cannot stat {}: {error}", path.display());
152	                continue;
153	            }
154	        }
155	        let mut hasher = Sha256::new();
156	        // 読んでいる間に伸びるファイルでも上限を超えない
157	        let mut reader = (&mut file).take(MAX_HASH_BYTES + 1);
158	        let mut buffer = vec![0u8; 64 * 1024];
159	        let mut total = 0u64;
160	        loop {
161	            match reader.read(&mut buffer) {
162	                Ok(0) => break,
163	                Ok(n) => {
164	                    total += n as u64;
165	                    hasher.update(&buffer[..n]);
166	                }
167	                Err(error) => {
168	                    last_error = format!("cannot read {}: {error}", path.display());
169	                    total = u64::MAX;
170	                    break;
171	                }
172	            }
173	        }
174	        if total == u64::MAX {
175	            continue;
176	        }
177	        if total > MAX_HASH_BYTES {
178	            return Err(format!("larger than {} MiB", MAX_HASH_BYTES / 1024 / 1024));
179	        }
180	        return Ok(hasher
181	            .finalize()
182	            .iter()
183	            .fold(String::new(), |mut hex, byte| {
184	                let _ = write!(hex, "{byte:02x}");
185	                hex
186	            }));
187	    }
188	    Err(last_error)
189	}
