191	/// PID ごとのコマンドライン。取れたものだけを返す
192	fn command_lines(os: Os, unknown: &[UnknownProcess]) -> HashMap<u32, String> {
193	    if unknown.is_empty() {
194	        return HashMap::new();
195	    }
196	    match os {
197	        Os::Linux => unknown
198	            .iter()
199	            .filter_map(|item| {
200	                let bytes = std::fs::read(format!("/proc/{}/cmdline", item.pid)).ok()?;
201	                let text = parse_proc_cmdline(&bytes);
202	                (!text.is_empty()).then_some((item.pid, text))
203	            })
204	            .collect(),
205	        Os::Windows => windows_command_lines(unknown.iter().map(|item| item.pid)),
206	    }
207	}
