209	/// `/proc/<pid>/cmdline`（NUL 区切り）を空白区切りの 1 行にする
210	fn parse_proc_cmdline(bytes: &[u8]) -> String {
211	    let text = String::from_utf8_lossy(bytes);
212	    text.trim_end_matches('\0').replace('\0', " ")
213	}
