            .collect();
        // 持ち主が分からない（権限が足りない、列挙の合間に終わった）ことも差分で見えるようにする
        if known.is_empty() {
            entry.insert("unknown".to_string());
        }
        entry.extend(known.into_iter().cloned());
    }

